    const 文本 = `${物品名} ${分类} ${toText(物品数据 && 物品数据.描述, '')}`;
    return 分类 === '一次性道具' || /奶瓶|定装|炮弹|炸弹|爆弹|弹\b|弹$/.test(文本);
