  function 构建魂导器装配数据_桥接(物品名 = '', 物品数据 = {}) {
    const 装配数据 = cloneJsonValue(物品数据 && typeof 物品数据 === 'object' && !Array.isArray(物品数据) ? 物品数据 : {}, {});
    装配数据.名称 = toText(物品名, 装配数据.名称 || '魂导器');
    装配数据.魂导等级 = 读取魂导等级_桥接(物品数据);
    装配数据.装备状态 = '已装配';
    装配数据.装备技能 = 构建魂导器装备技能_桥接(物品名, 物品数据);
    delete 装配数据.name;
    delete 装配数据.数量;
    delete 装配数据.批次;
    delete 装配数据.基础使用次数;
    delete 装配数据.剩余使用次数;
    delete 装配数据.使用效果;
    return 装配数据;
  }

  function 读取背包批次列表_桥接(记录 = {}) {
    const 来源 = 记录 && typeof 记录 === 'object' && !Array.isArray(记录) ? 记录 : {};
    return (Array.isArray(来源.批次) ? 来源.批次 : []).filter(
      批次 => 批次 && typeof 批次 === 'object' && !Array.isArray(批次) && toNumber(批次.数量, 0) > 0,
    );
  }

  function 读取背包总数量_桥接(记录 = {}) {
    const 来源 = 记录 && typeof 记录 === 'object' && !Array.isArray(记录) ? 记录 : {};
    const 普通数量 = Math.max(0, Math.floor(toNumber(来源.数量, 0)));
    const 批次数量 = 读取背包批次列表_桥接(来源).reduce(
      (总数, 批次) => 总数 + Math.max(0, Math.floor(toNumber(批次.数量, 0))),
      0,
    );
    return 普通数量 + 批次数量;
  }

  function 读取首个背包批次_桥接(记录 = {}) {
    return 读取背包批次列表_桥接(记录)[0] || null;
  }

  function 规范化背包批次_桥接(来源批次 = {}, 数量 = 1, fallback = {}) {
    const 来源 = 来源批次 && typeof 来源批次 === 'object' && !Array.isArray(来源批次) ? 来源批次 : {};
    const 有耐久 = 来源.耐久 !== undefined || fallback.耐久 !== undefined;
    const 输出 = {
      数量: Math.max(0, Math.floor(toNumber(数量 ?? 来源.数量, toNumber(来源.数量, 0)))),
      品质: 规范化物品经济品质_桥接(来源.品质 ?? fallback.品质, fallback.物品名 || '', fallback.分类 || ''),
      品质系数: Math.max(0.1, Math.min(2, toNumber(来源.品质系数 ?? fallback.品质系数, 1))),
      阶位: Math.max(0, Math.min(5, Math.floor(toNumber(来源.阶位 ?? fallback.阶位, 0)))),
      基础金属: toText(来源.基础金属 ?? fallback.基础金属, '').trim(),
      魂导等级: Math.max(0, Math.min(12, Math.floor(toNumber(来源.魂导等级 ?? fallback.魂导等级, 0)))),
      耐久: Math.max(0, Math.floor(toNumber(来源.耐久 ?? fallback.耐久, 0))),
      剩余使用次数: Math.max(0, Math.floor(toNumber(来源.剩余使用次数 ?? fallback.剩余使用次数 ?? fallback.基础使用次数, 0))),
      使用次数恢复至tick: Math.max(0, Math.floor(toNumber(来源.使用次数恢复至tick ?? fallback.使用次数恢复至tick, 0))),
      绑定者: toText(来源.绑定者 ?? fallback.绑定者, '').trim(),
      有效期至tick: Math.max(0, Math.floor(toNumber(来源.有效期至tick ?? fallback.有效期至tick, 0))),
    };
    const 融合参数 = 来源?.副职业参数?.融合参数 || fallback?.副职业参数?.融合参数;
    if (
      融合参数 &&
      typeof 融合参数 === 'object' &&
      !Array.isArray(融合参数) &&
      (融合参数.数量 !== undefined || 融合参数.融合率 !== undefined)
    ) {
      输出.副职业参数 = {
        融合参数: {
          数量: Math.max(1, Math.floor(toNumber(融合参数.数量, 1))),
          融合率: Math.max(0, Math.min(100, Math.floor(toNumber(融合参数.融合率, 100)))),
        },
      };
    }
    Object.keys(输出).forEach(键 => {
      const 值 = 输出[键];
      if (
        键 !== '数量' &&
        (值 === '' ||
          值 === '无' ||
          (键 !== '耐久' && 值 === 0 && !(键 === '剩余使用次数' && toNumber(来源.使用次数恢复至tick ?? fallback.使用次数恢复至tick, 0) > 0)) ||
          (键 === '耐久' && !有耐久) ||
          (键 === '阶位' && !(toNumber(来源.阶位 ?? fallback.阶位, 0) > 0)) ||
          (键 === '剩余使用次数' && !(来源.剩余使用次数 !== undefined || fallback.剩余使用次数 !== undefined || Number(fallback.基础使用次数 || 0) > 0)) ||
          (键 === '使用次数恢复至tick' && !(来源.使用次数恢复至tick !== undefined || fallback.使用次数恢复至tick !== undefined)) ||
          (键 === '魂导等级' && !(Number(来源.魂导等级 ?? fallback.魂导等级 ?? 0) > 0)) ||
          (键 === '品质' && 值 === '普通') ||
          (键 === '品质系数' && Number(值) === 1) ||
          (Array.isArray(值) && !值.length) ||
          (值 && typeof 值 === 'object' && !Array.isArray(值) && !Object.keys(值).length))
      ) {
        delete 输出[键];
      }
    });
    return 输出.数量 > 0 ? 输出 : null;
  }

  function 需要批次入库_桥接(数据 = {}) {
    const 来源 = 数据 && typeof 数据 === 'object' && !Array.isArray(数据) ? 数据 : {};
    if (Array.isArray(来源.批次) && 来源.批次.length) return true;
    if (来源.品质系数 !== undefined && Number(来源.品质系数) !== 1) return true;
    if (
      来源.副职业参数?.融合参数 &&
      typeof 来源.副职业参数.融合参数 === 'object' &&
      !Array.isArray(来源.副职业参数.融合参数) &&
      (来源.副职业参数.融合参数.数量 !== undefined || 来源.副职业参数.融合参数.融合率 !== undefined)
    ) return true;
    if (来源.耐久 !== undefined || toNumber(来源.基础耐久, 0) > 0) return true;
    if (来源.剩余使用次数 !== undefined || Number(来源.基础使用次数 || 0) > 0) return true;
    if (toText(来源.基础金属, '').trim()) return true;
    if (toNumber(来源.阶位, 0) > 0) return true;
    if (toNumber(来源.魂导等级, 0) > 0) return true;
    if (来源.基础耐久 !== undefined) return true;
    if (来源.基础使用次数 !== undefined) return true;
    if (toText(来源.绑定者, '').trim()) return true;
    if (toNumber(来源.有效期至tick, 0) > 0) return true;
    return false;
  }

  function 构建入库批次列表_桥接(数据 = {}, 数量 = 1, fallback = {}) {
    const 来源 = 数据 && typeof 数据 === 'object' && !Array.isArray(数据) ? 数据 : {};
    const 目标数量 = Math.max(0, Math.floor(toNumber(数量, toNumber(来源.数量, 0))));
    if (Array.isArray(来源.批次) && 来源.批次.length) {
      let 剩余 = 目标数量;
      const 批次列表 = [];
      来源.批次.forEach(批次 => {
        if (剩余 <= 0) return;
        const 可取 = Math.min(剩余, Math.max(0, Math.floor(toNumber(批次?.数量, 0))));
        const 新批次 = 规范化背包批次_桥接(批次, 可取, fallback);
        if (新批次) {
          批次列表.push(新批次);
          剩余 -= 可取;
        }
      });
      return 批次列表;
    }
    if (!需要批次入库_桥接(来源)) return [];
    const 批次 = 规范化背包批次_桥接(来源, 目标数量, fallback);
    return 批次 ? [批次] : [];
  }

  function 构建背包扣减值_桥接(记录 = {}, 数量 = 1) {
    if (!记录 || typeof 记录 !== 'object' || Array.isArray(记录)) return null;
    const 当前 = cloneJsonValue(记录, {});
    let 剩余扣减 = Math.max(1, Math.floor(toNumber(数量, 1)));
    const 批次列表 = 读取背包批次列表_桥接(当前).map(批次 => cloneJsonValue(批次, {}));
    for (const 批次 of 批次列表) {
      if (剩余扣减 <= 0) break;
      if (批次.剩余使用次数 !== undefined) {
        const 剩余次数 = Math.max(0, Math.floor(toNumber(批次.剩余使用次数, 0)));
        if (剩余次数 > 1) {
          批次.剩余使用次数 = 剩余次数 - 1;
          剩余扣减 -= 1;
          continue;
        }
        delete 批次.剩余使用次数;
      }
      const 当前批次数量 = Math.max(0, Math.floor(toNumber(批次.数量, 0)));
      const 扣减 = Math.min(当前批次数量, 剩余扣减);
      批次.数量 = 当前批次数量 - 扣减;
      剩余扣减 -= 扣减;
    }
    当前.批次 = 批次列表.filter(批次 => Math.max(0, toNumber(批次.数量, 0)) > 0);
    const 普通数量 = Math.max(0, Math.floor(toNumber(当前.数量, 0)));
    当前.数量 = 剩余扣减 > 0 ? Math.max(0, 普通数量 - 剩余扣减) : 普通数量;
    if (!当前.批次.length) delete 当前.批次;
    if (读取背包总数量_桥接(当前) <= 0) return null;
    if (当前.数量 <= 0 && 当前.批次) 当前.数量 = 0;
    return 当前;
  }

  function 合并背包状态记录_桥接(已有 = {}, 新增 = {}) {
    const 旧记录 = 已有 && typeof 已有 === 'object' && !Array.isArray(已有) ? 已有 : {};
    const 新记录 = 新增 && typeof 新增 === 'object' && !Array.isArray(新增) ? 新增 : {};
    const 合并 = {
      数量: Math.max(0, Math.floor(toNumber(旧记录.数量, 0))) + Math.max(0, Math.floor(toNumber(新记录.数量, 0))),
    };
    const 批次列表 = [
      ...读取背包批次列表_桥接(旧记录).map(批次 => cloneJsonValue(批次, {})),
      ...读取背包批次列表_桥接(新记录).map(批次 => cloneJsonValue(批次, {})),
    ];
    if (批次列表.length) 合并.批次 = 批次列表;
    else delete 合并.批次;
    if (合并.数量 <= 0 && 合并.批次) 合并.数量 = 0;
    return 读取背包总数量_桥接(合并) > 0 ? 合并 : {};
  }

  function 规范化交付需求_桥接(来源需求 = {}) {
    const 来源 = 来源需求 && typeof 来源需求 === 'object' && !Array.isArray(来源需求) ? 来源需求 : {};
    if (!Object.keys(来源).length) return null;
    const 类型 = toText(来源.类型, '物品').trim() || '物品';
    if (类型 !== '物品') return null;
    const 名称 = toText(来源.名称, '').trim();
    if (!名称) return null;
    const 数量 = Math.max(1, Math.floor(toNumber(来源.数量, 1)));
    const 品质下限 = toText(来源.品质下限, '').trim();
    const 输出 = { 类型: '物品', 名称, 数量 };
    if (物品经济品质集合_桥接.has(品质下限)) 输出.品质下限 = 品质下限;
    return 输出;
  }

  function 读取交付品质序号_桥接(品质 = '') {
    const 序号 = 物品经济品质列表_桥接.indexOf(toText(品质, '').trim());
    return 序号 >= 0 ? 序号 : 0;
  }

  function 读取交付候选品质_桥接(候选 = {}) {
    return 规范化物品经济品质_桥接(
      候选.品质 || 候选.品阶 || 候选.批次品质 || '普通',
      候选.物品名 || 候选.名称 || '',
      候选.物品分类 || 候选.分类 || '',
    );
  }

  function 交付候选达到品质下限_桥接(候选 = {}, 交付需求 = {}) {
    const 品质下限 = toText(交付需求 && 交付需求.品质下限, '').trim();
    if (!品质下限) return true;
    return 读取交付品质序号_桥接(读取交付候选品质_桥接(候选)) >= 读取交付品质序号_桥接(品质下限);
  }

  function 交付候选精确命中名称_桥接(候选 = {}, 需求名 = '') {
    const 名称 = toText(需求名, '').trim();
    if (!名称) return false;
    return [候选.物品名, 候选.名称].some(值 => toText(值, '').trim() === 名称);
  }

  function 交付候选包含命中名称_桥接(候选 = {}, 需求名 = '') {
    const 名称 = toText(需求名, '').trim();
    if (!名称) return false;
    return [候选.物品名, 候选.名称].some(值 => {
      const 候选名 = toText(值, '').trim();
      return 候选名 && (候选名.includes(名称) || 名称.includes(候选名));
    });
  }

  function 构建交付候选数据_桥接(根数据 = {}, 物品名 = '', 背包记录 = {}, 批次 = null, 批次索引 = -1) {
    const 命中定义 = 查找物品定义_桥接(根数据, 物品名);
    const 定义 = 命中定义?.定义 || {};
    const 分类 =
      命中定义?.分类 ||
      toText(背包记录 && (背包记录.物品分类 || 背包记录.分类), '') ||
      toText(定义.物品分类 || 定义.分类, '') ||
      推断物品分类(物品名, 定义, 背包记录);
    const 数量 = Math.max(0, Math.floor(toNumber(批次 ? 批次.数量 : 背包记录.数量, 0)));
    const 候选 = {
      ...(定义 || {}),
      物品分类: 分类,
      ...(背包记录 || {}),
      ...(批次 || {}),
      名称: 物品名,
      物品名,
      批次索引,
      数量,
    };
    delete 候选.批次;
    候选.品质系数 = Math.max(0.1, toNumber(候选.品质系数, 1));
    候选.魂导等级 = Math.max(0, Math.floor(toNumber(候选.魂导等级, 0)));
    return 候选;
  }

  function 交付候选满足需求_桥接(候选 = {}, 交付需求 = {}) {
    const 需求 = 规范化交付需求_桥接(交付需求);
    if (!需求) return false;
    return 交付候选达到品质下限_桥接(候选, 需求);
  }

  function 格式化交付需求文本_桥接(交付需求 = {}) {
    const 需求 = 规范化交付需求_桥接(交付需求);
    if (!需求) return '';
    const 片段 = [];
    const 名称 = toText(需求.名称, '').trim();
    const 数量 = Math.max(1, Math.floor(toNumber(需求.数量, 1)));
    if (名称) 片段.push(名称);
    片段.push(`×${数量}`);
    if (需求.品质下限) 片段.push(`品质≥${toText(需求.品质下限, '')}`);
    return 片段.filter(Boolean).join(' / ') || '物品交付';
  }

  function 收集交付候选列表_桥接(快照 = {}, 角色键 = '', 交付需求 = {}) {
    const 根数据 = 快照?.rootData || {};
    const 背包 = deepGet(根数据, ['char', 角色键, '背包'], {});
    if (!背包 || typeof 背包 !== 'object' || Array.isArray(背包)) return [];
    const 需求 = 规范化交付需求_桥接(交付需求);
    if (!需求) return [];
    const 需求名 = toText(需求.名称, '').trim();
    const 列表 = [];
    Object.entries(背包).forEach(([物品名, 背包记录]) => {
      if (!物品名 || !背包记录 || typeof 背包记录 !== 'object' || Array.isArray(背包记录)) return;
      const 普通数量 = Math.max(0, Math.floor(toNumber(背包记录.数量, 0)));
      if (普通数量 > 0) {
        const 候选 = 构建交付候选数据_桥接(根数据, 物品名, 背包记录, null, -1);
        列表.push(候选);
      }
      读取背包批次列表_桥接(背包记录).forEach((批次, 批次索引) => {
        const 候选 = 构建交付候选数据_桥接(根数据, 物品名, 背包记录, 批次, 批次索引);
        列表.push(候选);
      });
    });
    const 精确列表 = 列表.filter(候选 => 交付候选精确命中名称_桥接(候选, 需求名));
    const 可用列表 = (精确列表.length ? 精确列表 : 列表.filter(候选 => 交付候选包含命中名称_桥接(候选, 需求名))).filter(候选 =>
      交付候选满足需求_桥接(候选, 需求),
    );
    return 可用列表.sort((甲, 乙) => {
      const 甲品质差 = Math.max(0, 读取交付品质序号_桥接(读取交付候选品质_桥接(甲)) - 读取交付品质序号_桥接(需求.品质下限));
      const 乙品质差 = Math.max(0, 读取交付品质序号_桥接(读取交付候选品质_桥接(乙)) - 读取交付品质序号_桥接(需求.品质下限));
      if (甲品质差 !== 乙品质差) return 甲品质差 - 乙品质差;
      return toText(甲.物品名, '').localeCompare(toText(乙.物品名, ''), 'zh-Hans-CN');
    });
  }

  function 构建交付需求扣减补丁_桥接(快照 = {}, 角色键 = '', 交付需求 = {}) {
    const 需求 = 规范化交付需求_桥接(交付需求);
    const 需要数量 = Math.max(1, Math.floor(toNumber(需求 && 需求.数量, 1)));
    const 候选列表 = 收集交付候选列表_桥接(快照, 角色键, 需求);
    const 合格总数 = 候选列表.reduce((总数, 候选) => 总数 + Math.max(0, Math.floor(toNumber(候选.数量, 0))), 0);
    if (!需求 || 合格总数 < 需要数量) {
      return {
        ok: false,
        reason: `缺少合格交付物：${格式化交付需求文本_桥接(需求)}。`,
        patchOps: [],
      };
    }
    const 背包路径 = ['rootData', 'char', 角色键, '背包'];
    const 更新表 = new Map();
    const 消耗记录 = [];
    let 剩余数量 = 需要数量;
    候选列表.forEach(候选 => {
      if (剩余数量 <= 0) return;
      const 物品名 = toText(候选.物品名, '').trim();
      if (!物品名) return;
      const 现有记录 = 更新表.has(物品名)
        ? 更新表.get(物品名)
        : cloneJsonValue(deepGet(快照, [...背包路径, 物品名], {}), {});
      if (!现有记录 || typeof 现有记录 !== 'object' || Array.isArray(现有记录)) return;
      const 可扣数量 = Math.min(剩余数量, Math.max(0, Math.floor(toNumber(候选.数量, 0))));
      if (可扣数量 <= 0) return;
      if (候选.批次索引 >= 0) {
        const 批次列表 = Array.isArray(现有记录.批次) ? 现有记录.批次.map(批次 => cloneJsonValue(批次, {})) : [];
        const 批次 = 批次列表[候选.批次索引];
        if (!批次) return;
        批次.数量 = Math.max(0, Math.floor(toNumber(批次.数量, 0)) - 可扣数量);
        现有记录.批次 = 批次列表;
      } else {
        现有记录.数量 = Math.max(0, Math.floor(toNumber(现有记录.数量, 0)) - 可扣数量);
      }
      更新表.set(物品名, 现有记录);
      消耗记录.push({ 物品名, 数量: 可扣数量 });
      剩余数量 -= 可扣数量;
    });
    const 补丁列表 = [];
    更新表.forEach((记录, 物品名) => {
      if (Array.isArray(记录.批次)) {
        记录.批次 = 记录.批次.filter(批次 => Math.max(0, Math.floor(toNumber(批次 && 批次.数量, 0))) > 0);
        if (!记录.批次.length) delete 记录.批次;
      }
      if (记录.数量 === undefined && 记录.批次) 记录.数量 = 0;
      if (记录.数量 <= 0 && 记录.批次) 记录.数量 = 0;
      const 物品路径 = `/char/${escapeJsonPointerValue(角色键)}/背包/${escapeJsonPointerValue(物品名)}`;
      if (读取背包总数量_桥接(记录) <= 0) 补丁列表.push({ op: 'remove', path: 物品路径 });
      else 补丁列表.push({ op: 'replace', path: 物品路径, value: 记录 });
    });
    return {
      ok: 剩余数量 <= 0,
      reason: 剩余数量 <= 0 ? '' : `缺少合格交付物：${格式化交付需求文本_桥接(需求)}。`,
      patchOps: 剩余数量 <= 0 ? 补丁列表 : [],
      消耗文本: 消耗记录.map(记录 => `${记录.数量}份${记录.物品名}`).join('、'),
    };
  }

  function 估算交付需求总价_桥接(快照 = {}, 交付需求 = {}, 候选物品 = null) {
    const 需求 = 规范化交付需求_桥接(交付需求);
    if (!需求) return 0;
    const 名称 = toText(候选物品?.物品名 || 候选物品?.名称 || 需求.名称, '').trim();
    const 数量 = Math.max(1, Math.floor(toNumber(需求.数量, 1)));
    const 根数据 = 快照?.rootData || {};
    const 命中定义 = 名称 ? 查找物品定义_桥接(根数据, 名称) : null;
    const 估价物品 = {
      ...(命中定义?.定义 || {}),
      ...(候选物品 && typeof 候选物品 === 'object' && !Array.isArray(候选物品) ? 候选物品 : {}),
    };
    if (typeof window.__LWCS_RESOLVE_TRADE_ITEM_PRICE__ === 'function' && 名称) {
      try {
        const 估价结果 = window.__LWCS_RESOLVE_TRADE_ITEM_PRICE__(快照, 名称, {
          数量,
          物品: 估价物品,
          来源: '交付需求估价',
        });
        const 总价 = Math.max(0, Math.floor(toNumber(估价结果 && 估价结果.总价, 0)));
        if (总价 > 0) return 总价;
      } catch (错误) {}
    }
    const 基础价格 = Math.max(0, Math.floor(toNumber(估价物品.基础价格 || 估价物品.价格, 0)));
    const 品质系数 = Math.max(0.1, toNumber(估价物品.品质系数, 1));
    return Math.max(0, Math.floor(基础价格 * 品质系数 * 数量));
  }

  function 规范化物品定义分类_桥接(分类 = '', fallback = '剧情杂物') {
    const 文本 = toText(分类, '').trim();
    return 物品定义分类集合_桥接.has(文本) ? 文本 : fallback;
  }

  function 读取物品定义显式分类_桥接(定义 = {}, fallback = '') {
    const 来源 = 定义 && typeof 定义 === 'object' && !Array.isArray(定义) ? 定义 : {};
    return 规范化物品定义分类_桥接(来源.物品分类 || 来源.分类 || '', fallback);
  }

  function 要求物品定义分类_桥接(物品名 = '', 定义 = {}, 分类 = '') {
    const 分类名 = 规范化物品定义分类_桥接(分类 || 读取物品定义显式分类_桥接(定义, ''), '');
    if (!分类名) throw new Error(`物品定义缺少分类：${toText(物品名, '未命名') || '未命名'}`);
    return 分类名;
  }

  function 确保物品定义分类表_桥接(rootData = {}) {
    if (!rootData || typeof rootData !== 'object') return {};
    if (!rootData.物品 || typeof rootData.物品 !== 'object' || Array.isArray(rootData.物品)) rootData.物品 = {};
    物品定义分类列表_桥接.forEach(分类 => {
      if (!rootData.物品[分类] || typeof rootData.物品[分类] !== 'object' || Array.isArray(rootData.物品[分类]))
        rootData.物品[分类] = {};
    });
    return rootData.物品;
  }

  function 遍历物品定义_桥接(rootData = {}, 回调 = () => {}) {
    const 物品表 = rootData && rootData.物品 && typeof rootData.物品 === 'object' && !Array.isArray(rootData.物品) ? rootData.物品 : {};
    物品定义分类列表_桥接.forEach(分类 => {
      safeEntries(物品表[分类] || {}).forEach(([物品名, 定义]) => {
        if (物品名 && 定义 && typeof 定义 === 'object' && !Array.isArray(定义)) 回调(物品名, 定义, 分类);
      });
    });
  }

  function 取物品定义条目列表_桥接(rootData = {}) {
    const 列表 = [];
    遍历物品定义_桥接(rootData, (物品名, 定义, 分类) => 列表.push({ 物品名, 定义, 分类 }));
    return 列表;
  }


  function 查找物品定义_桥接(rootData = {}, 物品名 = '') {
    const 名称 = toText(物品名, '').trim();
    if (!名称) return null;
    let 结果 = null;
    遍历物品定义_桥接(rootData, (当前名, 定义, 分类) => {
      if (!结果 && 当前名 === 名称) 结果 = { 物品名: 当前名, 定义, 分类 };
    });
    return 结果;
  }

  function 物品定义存在_桥接(rootData = {}, 物品名 = '') {
    return !!查找物品定义_桥接(rootData, 物品名);
  }

  function 写入分类物品定义_桥接(rootData = {}, 物品名 = '', 定义 = {}, 分类 = '', 选项 = {}) {
    const 名称 = toText(物品名, '').trim();
    if (!名称) throw new Error('物品名称不能为空。');
    const 分类名 = 要求物品定义分类_桥接(名称, 定义, 分类);
    const 物品表 = 确保物品定义分类表_桥接(rootData);
    const 已有 = 查找物品定义_桥接(rootData, 名称);
    if (已有 && 已有.分类 !== 分类名 && !选项.允许覆盖) throw new Error(`同名物品已存在于【${已有.分类}】。`);
    物品定义分类列表_桥接.forEach(当前分类 => {
      if (当前分类 !== 分类名 && 物品表[当前分类]) delete 物品表[当前分类][名称];
    });
    物品表[分类名][名称] = 构建物品定义记录_桥接(名称, 定义, 分类名);
    return { 物品名: 名称, 分类: 分类名, 定义: 物品表[分类名][名称] };
  }

  function 删除分类物品定义_桥接(rootData = {}, 物品名 = '') {
    const 命中 = 查找物品定义_桥接(rootData, 物品名);
    if (!命中) return false;
    const 物品表 = 确保物品定义分类表_桥接(rootData);
    if (物品表[命中.分类]) delete 物品表[命中.分类][命中.物品名];
    return true;
  }

  function 取物品定义_桥接(rootData = {}, 物品名 = '') {
    return 查找物品定义_桥接(rootData, 物品名)?.定义 || {};
  }

  function 合并物品定义与状态_桥接(rootData = {}, 物品名 = '', 状态 = {}) {
    const 安全状态 = 状态 && typeof 状态 === 'object' && !Array.isArray(状态) ? 状态 : {};
    const 命中 = 查找物品定义_桥接(rootData, 物品名);
    const 首批 = 读取首个背包批次_桥接(安全状态);
    return {
      ...(命中?.定义 || {}),
      ...安全状态,
      ...(首批 || {}),
      物品分类: 命中?.分类 || 安全状态.物品分类 || '',
      数量: 读取背包总数量_桥接(安全状态),
    };
  }

  function 构建物品定义记录_桥接(物品名 = '', 数据 = {}, 分类 = '') {
    const 来源 = 数据 && typeof 数据 === 'object' && !Array.isArray(数据) ? 数据 : {};
    const 物品分类 = 要求物品定义分类_桥接(物品名, 来源, 分类);
    const 记录 = {
      品质: 规范化物品经济品质_桥接(来源.品质 || 来源.品阶 || '普通', 物品名, 物品分类),
      描述: toText(来源.描述, `关于【${物品名}】的记录暂未展开。`),
      基础价格: Math.max(1, Math.floor(toNumber(来源.基础价格, 1))),
      默认货币: toText(来源.默认货币, ''),
    };
    if (物品分类 === '魂技造物' && toText(来源.名称, '').trim() && toText(来源.名称, '').trim() !== 物品名) {
      记录.名称 = toText(来源.名称, '').trim();
    }
    if (物品分类 === '魂灵') {
      const 魂灵品质 = normalizeSoulSpiritQuality(来源.魂灵品质 || '');
      if (魂灵品质) 记录.魂灵品质 = 魂灵品质;
      if (toText(来源.表象名称, '').trim() && toText(来源.表象名称, '').trim() !== '无') 记录.表象名称 = toText(来源.表象名称, '').trim();
      if (toText(来源.标准物种, '').trim() && toText(来源.标准物种, '').trim() !== '无') 记录.标准物种 = toText(来源.标准物种, '').trim();
      if (toNumber(来源.年限, 0) > 0) 记录.年限 = Math.max(0, Math.floor(toNumber(来源.年限, 0)));
      Object.keys(记录).forEach(键 => {
        const 值 = 记录[键];
        if (值 === undefined || 值 === null || 值 === '' || (Array.isArray(值) && !值.length)) delete 记录[键];
        else if (值 && typeof 值 === 'object' && !Array.isArray(值) && !Object.keys(值).length) delete 记录[键];
      });
      return 记录;
    }
    if (物品分类 === '锻造金属') {
      记录.阶位 = Math.max(0, Math.min(5, Math.floor(toNumber(来源.阶位, 0))));
      const 金属特性 = Array.isArray(来源.金属特性)
        ? [...new Set(来源.金属特性.map(特性 => toText(特性, '').trim()).filter(Boolean))]
        : [];
      if (金属特性.length) 记录.金属特性 = 金属特性;
    }
    const 魂导等级 = 读取魂导等级_桥接(来源);
    const 是魂导器 = 魂导等级 > 0 && !判断一次性魂导道具_桥接(物品名, { ...来源, 物品分类 });
    if (魂导等级 > 0) 记录.魂导等级 = 魂导等级;
    if (Number(来源.基础使用次数 || 0) > 0) 记录.基础使用次数 = Math.max(1, Math.floor(toNumber(来源.基础使用次数, 1)));
    if (来源.使用次数恢复周期 !== undefined) {
      const 使用次数恢复周期 = toText(来源.使用次数恢复周期, '').trim();
      if (使用次数恢复周期 !== '每日') throw new Error(`物品定义使用次数恢复周期无效：${物品名}`);
      记录.使用次数恢复周期 = 使用次数恢复周期;
    }
    if (来源.使用后消耗 !== undefined) {
      if (typeof 来源.使用后消耗 !== 'boolean') throw new Error(`物品定义使用后消耗无效：${物品名}`);
      记录.使用后消耗 = 来源.使用后消耗;
    }
    const 是装备定义 = 判断物品为装备_桥接(物品名, { ...来源, 物品分类 });
    if (是装备定义 || 是魂导器) {
      const 是常规装备 = 判断常规装备定义_桥接(物品分类, 是魂导器);
      if (toText(来源.装备槽位, '')) 记录.装备槽位 = toText(来源.装备槽位, '');
      if (toNumber(来源.基础耐久, 0) > 0) 记录.基础耐久 = Math.max(0, Math.floor(toNumber(来源.基础耐久, 0)));
      if (是常规装备) {
        const 加成方向 = 规范化装备加成方向_桥接(来源.加成方向 || []);
        if (加成方向.length) 记录.加成方向 = 加成方向;
      }
      if (来源.属性加成 && typeof 来源.属性加成 === 'object' && !Array.isArray(来源.属性加成)) {
        const 属性加成 = {};
        装备加成属性选项_桥接.forEach(属性 => {
          const 值 = 来源.属性加成[属性];
          if (Number.isFinite(Number(值)) || /^[-+]?\d+(?:\.\d+)?%$/.test(toText(值, '').trim())) 属性加成[属性] = cloneJsonValue(值, 值);
        });
        if (Object.keys(属性加成).length) 记录.属性加成 = 属性加成;
      }
      if (物品分类 === '魂骨' && 来源.属性倍率 && typeof 来源.属性倍率 === 'object' && !Array.isArray(来源.属性倍率)) 记录.属性倍率 = 归一化魂骨属性倍率_桥接(来源.属性倍率);
      if (物品分类 !== '魂骨' && 来源.装备技能 && typeof 来源.装备技能 === 'object' && !Array.isArray(来源.装备技能)) 记录.装备技能 = cloneJsonValue(来源.装备技能, {});
      if (来源.附带魂技 && typeof 来源.附带魂技 === 'object' && !Array.isArray(来源.附带魂技)) 记录.附带魂技 = cloneJsonValue(来源.附带魂技, {});
    }
    if (物品分类 === '魂骨') {
      const 附带技能 = 来源.附带技能 && typeof 来源.附带技能 === 'object' && !Array.isArray(来源.附带技能)
        ? 来源.附带技能
        : 来源.装备技能;
      if (附带技能 && typeof 附带技能 === 'object' && !Array.isArray(附带技能)) 记录.附带技能 = cloneJsonValue(附带技能, {});
      if (toNumber(来源.年限, 0) > 0) 记录.年限 = Math.max(0, Math.floor(toNumber(来源.年限, 0)));
    }
    if (可使用物品分类集合_桥接.has(物品分类)) {
      if (Array.isArray(来源.使用效果) && 来源.使用效果.length) {
        记录.使用效果 = cloneJsonValue(来源.使用效果, []).map(效果 => {
          if (!效果 || typeof 效果 !== 'object' || Array.isArray(效果)) return 效果;
          const 清理效果 = cloneJsonValue(效果, {});
          delete 清理效果.描述;
          return 清理效果;
        });
      }
      if (Array.isArray(来源.副作用列表) && 来源.副作用列表.length) 记录.副作用列表 = cloneJsonValue(来源.副作用列表, []);
    }
    if (来源.解锁内容 !== undefined) 记录.解锁内容 = cloneJsonValue(来源.解锁内容);
    if (物品分类 === '修炼秘籍') {
      if (来源.获取条件 !== undefined) 记录.获取条件 = cloneJsonValue(来源.获取条件);
      if (来源.研读条件 !== undefined) 记录.研读条件 = cloneJsonValue(来源.研读条件);
    }
    if (物品分类 === '设计图纸') {
      ['图纸目标', '材料'].forEach(字段名 => {
        if (来源[字段名] !== undefined && toText(来源[字段名], '').trim()) 记录[字段名] = cloneJsonValue(来源[字段名]);
      });
    }
    if (['身份凭证', '入场凭证'].includes(物品分类) && toText(来源.使用限制或归属说明, '').trim()) 记录.使用限制或归属说明 = toText(来源.使用限制或归属说明, '').trim();
    Object.keys(记录).forEach(键 => {
      const 值 = 记录[键];
      if (值 === undefined || 值 === null || 值 === '' || (Array.isArray(值) && !值.length)) delete 记录[键];
      else if (值 && typeof 值 === 'object' && !Array.isArray(值) && !Object.keys(值).length) delete 记录[键];
    });
    return 记录;
  }

  function 构建背包状态记录_桥接(数据 = {}, 数量 = 1) {
    const 来源 = 数据 && typeof 数据 === 'object' && !Array.isArray(数据) ? 数据 : {};
    const 目标数量 = Math.max(1, Math.floor(toNumber(数量, toNumber(来源.数量, 1))));
    const 批次列表 = 构建入库批次列表_桥接(来源, 目标数量, {
      物品名: toText(来源.名称 || 来源.name, ''),
      分类: toText(来源.物品分类 || 来源.分类, ''),
      品质: 来源.批次品质 || 来源.品质,
      品质系数: 来源.品质系数,
      阶位: 来源.阶位,
      基础金属: 来源.基础金属,
      魂导等级: 来源.魂导等级,
      耐久: 来源.耐久 ?? 来源.基础耐久,
      剩余使用次数: 来源.剩余使用次数,
      基础耐久: 来源.基础耐久,
      基础使用次数: 来源.基础使用次数,
      使用次数恢复至tick: 来源.使用次数恢复至tick,
      绑定者: 来源.绑定者,
      有效期至tick: 来源.有效期至tick,
      副职业参数: 来源?.副职业参数?.融合参数 ? { 融合参数: 来源.副职业参数.融合参数 } : undefined,
    });
    return 批次列表.length ? { 数量: 0, 批次: 批次列表 } : { 数量: 目标数量 };
  }


  function 推断物品分类(物品名 = '', 物品定义 = {}, 背包状态 = {}) {
    const 名称文本 = toText(物品名, '');
    const 定义 = 物品定义 && typeof 物品定义 === 'object' && !Array.isArray(物品定义) ? 物品定义 : {};
    const 状态 = 背包状态 && typeof 背包状态 === 'object' && !Array.isArray(背包状态) ? 背包状态 : {};
    const 分类文本 = toText(定义.物品分类 || 定义.分类, '');
    const 槽位文本 = toText(定义.装备槽位 || 状态.装备槽位, '无');
    const 品质文本 = toText(定义.品质 || 状态.品质, '');
    const 描述文本 = toText(定义.描述 || 状态.描述, '');
    const 合并文本 = `${名称文本} ${分类文本} ${槽位文本} ${品质文本} ${描述文本}`;
    if (/魂骨|外附骨|头部骨|躯干骨|左臂骨|右臂骨|左腿骨|右腿骨/.test(合并文本) || 分类文本 === '魂骨') return '魂骨';
    if (分类文本 === '近战武器') return '武器';
    if (分类文本 === '远程武器') return 判断可装配魂导器_桥接(物品名, 定义) ? '武器' : (Array.isArray(定义.使用效果) && 定义.使用效果.length ? '消耗品' : '武器');
    if (槽位文本 && 槽位文本 !== '无') return '装备';
    if (/装备|武器|防具|斗铠|机甲|神器|超神器/.test(分类文本 + 名称文本)) return '装备';
    if (/灵物|仙草|药草|灵草|丹药|灵药/.test(合并文本)) return '灵物';
    if (/金属|矿石|沉银|魔银|星铁|精金|秘银|锻金|灵锻|魂锻|天锻/.test(合并文本)) return '金属';
    if (Array.isArray(定义.使用效果) && 定义.使用效果.length) return '消耗品';
    if (/消耗|药剂|食物|补给|一次性|魂技造物/.test(分类文本)) return '消耗品';
    if (分类文本 === '身份凭证' || /身份凭证|徽章|身份象征/.test(合并文本)) return '身份凭证';
    if (分类文本 === '入场凭证' || /入场凭证|门票|通行证/.test(合并文本)) return '入场凭证';
    return '杂项';
  }



  function 格式化物品字段值(值) {
    if (值 === undefined || 值 === null) return '';
    if (typeof 值 === 'number' || typeof 值 === 'boolean') return String(值);
    if (typeof 值 === 'string') return 值;
    return '';
  }

  function 格式化物品结构字段值(值) {
    if (值 === undefined || 值 === null || 值 === '') return '';
    if (typeof 值 === 'string') return 值;
    try {
      return JSON.stringify(值, null, 2);
    } catch (error) {}
    return '';
  }

  const 物品品质选项_桥接 = 物品经济品质列表_桥接;
  const 魂灵品质选项_桥接 = Object.freeze(['F', 'D', 'C', 'B', 'A', 'S', 'S+']);
  function 读取物品货币选项_桥接(数据根 = {}) {
    return 读取当前时代钱包配置_桥接(数据根).currencies.map(货币 => 货币.key);
  }
  const 物品装备槽位选项_桥接 = Object.freeze(['无', '头部', '躯干', '左臂', '右臂', '左腿', '右腿', '武器', '防具', '饰品']);
  const 装备加成属性选项_桥接 = Object.freeze(['魂力上限', '精神力上限', '力量', '防御', '敏捷', '体力上限']);
  const 装备加成方向选项_桥接 = Object.freeze([...装备加成属性选项_桥接, '全属性']);
  const 装备加成属性集合_桥接 = new Set(装备加成属性选项_桥接);
  const 正式技能字段列表_桥接 = Object.freeze(['魂技名', '画面描述', '效果描述', '产物描述', '承载方式', '消耗', '前摇', '场外冷却至tick', '附带属性', '使用条件', '技能掌控度', '触发限制', '_效果数组', '副作用列表']);
  const 正式技能字段集合_桥接 = new Set(正式技能字段列表_桥接);

  function 断言物品正式技能_桥接(技能 = {}, 来源 = '物品技能') {
    const 技能名 = toText(技能?.魂技名, '').trim() || 来源;
    const 未知字段 = Object.keys(技能 || {}).filter(字段名 => !正式技能字段集合_桥接.has(字段名));
    if (未知字段.length) throw new Error(`技能【${技能名}】包含未知字段：${未知字段.join('、')}`);
    ['魂技名', '画面描述', '效果描述', '承载方式'].forEach(字段名 => {
      if (!toText(技能?.[字段名], '').trim()) throw new Error(`技能【${技能名}】缺少${字段名}。`);
    });
    if (技能.消耗 === undefined) throw new Error(`技能【${技能名}】缺少消耗。`);
    if (!Number.isFinite(Number(技能.前摇))) throw new Error(`技能【${技能名}】的前摇必须是数值。`);
    if (!Array.isArray(技能._效果数组) || !技能._效果数组.length) throw new Error(`技能【${技能名}】缺少可执行效果数组。`);
    断言技能设计台效果数组契约(技能._效果数组, `${来源}.${技能名}._效果数组`);
    return 技能;
  }
  const 装备加成方向集合_桥接 = new Set(装备加成方向选项_桥接);
  const 物品属性选项_桥接 = 装备加成属性选项_桥接;


  function 判断常规装备定义_桥接(物品分类 = '', 是魂导器 = false, 定义 = {}) {
    const 分类 = toText(物品分类, '').trim();
    if (['近战武器', '远程武器', '防具装备', '战术装备', '功能道具'].includes(分类) || !!是魂导器) return true;
    const 槽位 = toText(定义?.装备槽位, '').trim();
    return !!槽位 && 槽位 !== '无' && !['魂骨', '斗铠部件', '机甲机体'].includes(分类);
  }

  function 规范化装备加成方向_桥接(来源方向 = []) {
    const 原始列表 = Array.isArray(来源方向)
      ? 来源方向
      : toText(来源方向, '')
        .split(/[,\n，、|/]+/)
        .map(片段 => 片段.trim());
    const 输出 = [];
    原始列表.forEach(方向 => {
      const 文本 = toText(方向, '').trim();
      if (!文本 || !装备加成方向集合_桥接.has(文本) || 输出.includes(文本)) return;
      输出.push(文本);
    });
    return 输出;
  }


  function 判断物品为装备_桥接(物品名 = '', 定义 = {}) {
    const 类型 = toText(定义 && (定义.物品分类 || 定义.分类), '');
    const 槽位 = toText(定义 && 定义.装备槽位, '无');
    if (判断可装配魂导器_桥接(物品名, 定义)) return true;
    if (类型 === '远程武器') return false;
    return 装备物品分类集合_桥接.has(类型) || 槽位 !== '无' || /装备|武具|防具|武器|饰品|斗铠|机甲|神器/.test(`${物品名} ${类型}`);
  }





















  function 解析物品表单值(原始值 = '') {
    const 文本 = toText(原始值, '').trim();
    if (!文本) return '';
    if (文本 === 'true') return true;
    if (文本 === 'false') return false;
    const 数值 = Number(文本);
    if (Number.isFinite(数值) && /^-?\d+(?:\.\d+)?$/.test(文本)) return 数值;
    return 文本;
  }

  function 解析物品结构表单值(原始值 = '') {
    const 文本 = toText(原始值, '').trim();
    if (!文本) return '';
    if (/^[\[{"]/.test(文本) || ['true', 'false', 'null'].includes(文本) || /^-?\d+(?:\.\d+)?$/.test(文本)) {
      try {
        return JSON.parse(文本);
      } catch (error) {}
    }
    return 文本;
  }

  function 读取物品定义输入值(表单节点, 字段名 = '', 默认值 = '') {
    const 输入 = 表单节点 ? 表单节点.querySelector(`[data-item-definition-input="${字段名}"]`) : null;
    return toText(输入 && 'value' in 输入 ? 输入.value : 默认值, 默认值).trim();
  }

  function 写入物品嵌套键(目标对象, 键名 = '', 值 = '') {
    const 路径 = toText(键名, '')
      .split('.')
      .map(片段 => 片段.trim())
      .filter(Boolean);
    if (!路径.length) return;
    deepSetMutable(目标对象, 路径, 值);
  }

  function 读取物品键值对象(表单节点, 字段名 = '') {
    const 输出 = {};
    const 容器 = 表单节点 ? 表单节点.querySelector(`[data-item-definition-kv-list="${字段名}"]`) : null;
    if (!容器) return 输出;
    容器.querySelectorAll('[data-item-definition-kv]').forEach(行节点 => {
      const 键节点 = 行节点.querySelector('[data-item-definition-kv-key]');
      const 值节点 = 行节点.querySelector('[data-item-definition-kv-value]');
      const 键名 = toText(键节点 && 'value' in 键节点 ? 键节点.value : '', '').trim();
      if (!键名) return;
      写入物品嵌套键(输出, 键名, 解析物品表单值(值节点 && 'value' in 值节点 ? 值节点.value : ''));
    });
    return 输出;
  }

  function 读取物品加成方向列表(表单节点) {
    return 规范化装备加成方向_桥接(
      Array.from(表单节点 ? 表单节点.querySelectorAll('[data-item-definition-direction]:checked') : [])
        .map(输入 => toText(输入 && 'value' in 输入 ? 输入.value : '', '').trim())
        .filter(Boolean),
    );
  }

  function 读取物品使用效果列表(表单节点, 旧效果列表 = []) {
    const 容器 = 表单节点 ? 表单节点.querySelector('[data-item-definition-effect-list]') : null;
    if (容器 && 容器.matches('[data-skill-designer-prototype-grid]')) {
      return 读取技能设计台原型效果状态(容器, '自身', '', true, { 强制独立: true, 允许对应等级: true });
    }
    const 输出 = [];
    if (!容器) return 输出;
    容器.querySelectorAll('[data-item-definition-effect-row]').forEach(行节点 => {
      const 序号 = Math.max(0, Math.floor(toNumber(行节点.getAttribute('data-item-effect-index'), 输出.length)));
      const 旧效果 =
        Array.isArray(旧效果列表) && 旧效果列表[序号] && typeof 旧效果列表[序号] === 'object'
          ? cloneJsonValue(旧效果列表[序号], {})
          : {};
      const 取值 = 字段名 => {
        const 节点 = 行节点.querySelector(`[data-item-effect-field="${字段名}"]`);
        return toText(节点 && 'value' in 节点 ? 节点.value : '', '').trim();
      };
      const 原型 = 取值('原型');
      const 目标 = 取值('目标');
      const 属性 = 取值('属性');
      const 数值原文 = 取值('数值');
      const 描述 = 取值('描述');
      if (!原型 && !目标 && !属性 && !数值原文 && !描述) return;
      const 新效果 = { ...旧效果 };
      if (原型) 新效果.原型 = 原型 === '自定义' ? toText(旧效果.原型, '自定义') : 原型;
      if (目标) 新效果.目标 = 目标;
      if (属性) 新效果.属性 = 属性;
      if (数值原文 !== '') 新效果.数值 = 解析物品表单值(数值原文);
      delete 新效果.描述;
      输出.push(新效果);
    });
    return 输出;
  }

  function 读取物品使用副作用列表(表单节点) {
    const 容器 = 表单节点 ? 表单节点.querySelector('[data-item-definition-side-effect-list]') : null;
    return 规范化技能设计台副作用列表(
      Array.from(容器 ? 容器.querySelectorAll('[data-skill-designer-side-effect-row]') : []).map(行节点 => {
        const 条目 = {};
        行节点.querySelectorAll('[data-skill-designer-side-effect-field]').forEach(输入 => {
          const 字段名 = normalizeSkillUiText(输入.getAttribute('data-skill-designer-side-effect-field'), '');
          if (!字段名) return;
          const 值 =
            输入 instanceof HTMLInputElement || 输入 instanceof HTMLSelectElement || 输入 instanceof HTMLTextAreaElement
              ? normalizeSkillUiText(输入.value, '')
              : '';
          if (值 || ['触发概率', '持续回合'].includes(字段名)) 条目[字段名] = 值;
        });
        return 条目;
      }),
    );
  }

  function 读取物品装备技能表(表单节点, 旧技能表 = {}) {
    const 输出 = {};
    const 容器 = 表单节点 ? 表单节点.querySelector('[data-item-definition-skill-list]') : null;
    if (!容器) return 输出;
    容器.querySelectorAll('[data-item-definition-skill-row]').forEach(行节点 => {
      const 旧键名 = toText(行节点.getAttribute('data-item-skill-old-key'), '').trim();
      const 旧技能 =
        旧键名 && 旧技能表 && typeof 旧技能表 === 'object' && 旧技能表[旧键名] && typeof 旧技能表[旧键名] === 'object'
          ? cloneJsonValue(旧技能表[旧键名], {})
          : {};
      const 取值 = 字段名 => {
        const 节点 = 行节点.querySelector(`[data-item-skill-field="${字段名}"]`);
        return toText(节点 && 'value' in 节点 ? 节点.value : '', '').trim();
      };
      const 键名 = 取值('键名') || 取值('魂技名');
      if (!键名) return;
      const 技能数据节点 = 行节点.querySelector('[data-item-skill-field="技能数据"]');
      const 解析技能 = 解析物品结构表单值(技能数据节点 && 'value' in 技能数据节点 ? 技能数据节点.value : '');
      const 技能 = 解析技能 && typeof 解析技能 === 'object' && !Array.isArray(解析技能) ? cloneJsonValue(解析技能, {}) : { ...旧技能 };
      技能.魂技名 = 取值('魂技名') || toText(技能.魂技名, 键名);
      断言物品正式技能_桥接(技能);
      输出[键名] = 技能;
    });
    return 输出;
  }

  // 读取器：默认读 DOM 表单；座舱传草稿读取器（同一套字段、同一套规范化）
  function 读取物品定义表单(表单节点, 数据根 = {}, 读取器 = null) {
    if (!表单节点 && !读取器) throw new Error('未找到物品定义表单。');
    const R = 读取器 || 物品定义DOM读取器(表单节点);
    const 旧名 = toText(R.旧名(), '').trim();
    const 新名 = R.值('名称', 旧名);
    if (!新名) throw new Error('物品名称不能为空。');
    const 旧命中 = 查找物品定义_桥接(数据根, 旧名 || 新名);
    const 旧定义 = cloneJsonValue(旧命中?.定义 || {}, {});
    const 时代货币选项 = 读取物品货币选项_桥接(数据根);
    const 默认时代货币 = 时代货币选项[0] || '';
    const 分类 = 规范化物品定义分类_桥接(
      R.值('物品分类', 旧命中?.分类 || 读取物品定义显式分类_桥接(旧定义, '剧情杂物')),
      '剧情杂物',
    );
    const 定义 = {
      品质: 规范化物品经济品质_桥接(
        R.值('品质', toText(旧定义.品质, '普通')) || '普通',
        新名,
        分类,
      ),
      描述: R.值('描述', toText(旧定义.描述, '')),
      基础价格: Math.max(1, Math.floor(toNumber(R.值('基础价格', 旧定义.基础价格), 1))),
      默认货币: R.值('默认货币', toText(旧定义.默认货币, 默认时代货币)) || 默认时代货币,
    };
    if (!时代货币选项.includes(定义.默认货币)) throw new Error(`货币【${定义.默认货币 || '空'}】不属于当前时代。`);
    if (分类 === '魂灵') {
      const 魂灵品质 = normalizeSoulSpiritQuality(R.值('魂灵品质', toText(旧定义.魂灵品质, '')));
      const 表象名称 = R.值('表象名称', toText(旧定义.表象名称, '')).trim();
      const 标准物种 = R.值('标准物种', toText(旧定义.标准物种, '')).trim();
      const 年限 = Math.max(0, Math.floor(toNumber(R.值('年限', 旧定义.年限), 0)));
      if (魂灵品质) 定义.魂灵品质 = 魂灵品质;
      if (表象名称 && 表象名称 !== '无') 定义.表象名称 = 表象名称;
      if (标准物种 && 标准物种 !== '无') 定义.标准物种 = 标准物种;
      if (年限 > 0) 定义.年限 = 年限;
      return { 旧名, 新名, 分类, 定义: 构建物品定义记录_桥接(新名, 定义, 分类) };
    }
    if (分类 === '锻造金属') 定义.阶位 = Math.max(0, Math.min(5, Math.floor(toNumber(R.值('阶位', 旧定义.阶位), 0))));
    const 魂导等级 = Math.max(0, Math.min(12, Math.floor(toNumber(R.值('魂导等级', 旧定义.魂导等级), 0))));
    if (魂导等级 > 0) 定义.魂导等级 = 魂导等级;
    const 装备槽位 = R.值('装备槽位', toText(旧定义.装备槽位, '无')) || '无';
    const 是魂导器 = 魂导等级 > 0 && !判断一次性魂导道具_桥接(新名, { ...旧定义, 物品分类: 分类 });
    const 是常规装备 = 判断常规装备定义_桥接(分类, 是魂导器, { ...旧定义, 装备槽位 });
    const 是装备定义 = 判断物品为装备_桥接(新名, { ...旧定义, 物品分类: 分类, 装备槽位 });
    if (是装备定义 || 是魂导器) {
      if (装备槽位 && 装备槽位 !== '无') 定义.装备槽位 = 装备槽位;
      定义.基础耐久 = Math.max(0, Math.floor(toNumber(R.值('基础耐久', 旧定义.基础耐久), 0)));
    }
    const 使用效果 = R.效果(旧定义.使用效果);
    const 使用副作用列表 = R.副作用();
    const 属性加成 = R.键值('属性加成');
    const 加成方向 = R.方向();
    const 装备技能 = R.技能(旧定义.附带技能 || 旧定义.装备技能);
    if (可使用物品分类集合_桥接.has(分类) && 使用效果.length) 定义.使用效果 = 使用效果;
    if (可使用物品分类集合_桥接.has(分类) && 使用副作用列表.length) 定义.副作用列表 = 使用副作用列表;
    if (是常规装备 && 加成方向.length) 定义.加成方向 = 加成方向;
    if ((是装备定义 || 是魂导器) && Object.keys(属性加成).length) 定义.属性加成 = 属性加成;
    if ((是装备定义 || 是魂导器) && Object.keys(装备技能).length) {
      if (分类 === '魂骨') 定义.附带技能 = 装备技能;
      else 定义.装备技能 = 装备技能;
    }
    if (分类 === '设计图纸') {
      ['图纸目标', '材料'].forEach(字段名 => {
        const 原始值 = R.值(字段名, '');
        const 字段值 = 字段名 === '材料' ? 解析物品结构表单值(原始值) : 原始值;
        if (字段值) 定义[字段名] = 字段值;
      });
    }
    if (旧定义.解锁内容 !== undefined) 定义.解锁内容 = cloneJsonValue(旧定义.解锁内容);
    if (旧定义.使用限制或归属说明 !== undefined) 定义.使用限制或归属说明 = toText(旧定义.使用限制或归属说明, '').trim();
    if (分类 === '修炼秘籍') {
      ['获取条件', '研读条件', '解锁内容'].forEach(字段名 => {
        const 字段值 = 解析物品结构表单值(R.值(字段名, ''));
        if (字段值 !== '') 定义[字段名] = 字段值;
      });
    }
    return { 旧名, 新名, 分类, 定义: 构建物品定义记录_桥接(新名, 定义, 分类) };
  }

  function 物品定义DOM读取器(表单节点) {
    return {
      旧名: () => toText(表单节点.getAttribute('data-item-definition-old-name'), ''),
      值: (字段名, 默认值 = '') => 读取物品定义输入值(表单节点, 字段名, 默认值),
      效果: 旧效果列表 => 读取物品使用效果列表(表单节点, 旧效果列表),
      副作用: () => 读取物品使用副作用列表(表单节点),
      键值: 字段名 => 读取物品键值对象(表单节点, 字段名),
      方向: () => 读取物品加成方向列表(表单节点),
      技能: 旧技能表 => 读取物品装备技能表(表单节点, 旧技能表),
    };
  }
  // 座舱草稿：{ 旧名, 字段: {名称, 物品分类, …, 材料(文本)}, 属性加成: [[键, 值]], 加成方向: [], 使用效果: [], 副作用列表: [], 技能: [{ 键, 魂技名, 新 }] }
  function 物品定义草稿读取器(草稿 = {}) {
    const 字段 = 草稿.字段 && typeof 草稿.字段 === 'object' ? 草稿.字段 : {};
    const 新技能 = 名称 => 断言物品正式技能_桥接({
      魂技名: 名称, 画面描述: '待设计', 效果描述: '待设计', 承载方式: '直接生效', 消耗: {}, 前摇: 0,
      _效果数组: [创建技能设计台默认原型效果('伤害结算', '单体')],
    });
    return {
      旧名: () => toText(草稿.旧名, ''),
      值: (字段名, 默认值 = '') => toText(字段[字段名] === undefined || 字段[字段名] === null ? 默认值 : 字段[字段名], 默认值).trim(),
      效果: () => (Array.isArray(草稿.使用效果) ? 草稿.使用效果 : []).filter(效果 => 效果 && typeof 效果 === 'object').map(效果 => {
        const 新效果 = cloneJsonValue(效果, {});
        Object.keys(新效果).forEach(键 => { if (typeof 新效果[键] === 'string') 新效果[键] = 解析物品表单值(新效果[键]); });
        return 新效果;
      }),
      副作用: () => 规范化技能设计台副作用列表((Array.isArray(草稿.副作用列表) ? 草稿.副作用列表 : []).map(条目 => cloneJsonValue(条目, {}))),
      键值: 字段名 => {
        const 输出 = {};
        (Array.isArray(草稿[字段名]) ? 草稿[字段名] : []).forEach(([键, 值] = []) => { const 键名 = toText(键, '').trim(); if (键名) 写入物品嵌套键(输出, 键名, 解析物品表单值(值)); });
        return 输出;
      },
      方向: () => 规范化装备加成方向_桥接(Array.isArray(草稿.加成方向) ? 草稿.加成方向 : []),
      技能: 旧技能表 => {
        const 输出 = {};
        (Array.isArray(草稿.技能) ? 草稿.技能 : []).forEach(行 => {
          const 键名 = toText(行 && (行.键 || 行.魂技名), '').trim();
          if (!键名) return;
          const 旧技能 = !行.新 && 旧技能表 && typeof 旧技能表 === 'object' && 旧技能表[键名] && typeof 旧技能表[键名] === 'object' ? cloneJsonValue(旧技能表[键名], {}) : null;
          输出[键名] = 旧技能 ? 断言物品正式技能_桥接({ ...旧技能, 魂技名: toText(行.魂技名, 旧技能.魂技名 || 键名) }) : 新技能(toText(行.魂技名, 键名));
        });
        return 输出;
      },
    };
  }
  // 现有定义 → 座舱草稿（结构字段转成文本，与原项目编辑器显示一致）；新建时给默认值
  function 构建物品定义草稿_桥接(物品名 = '', 数据根 = {}) {
    const 命中 = 物品名 ? 查找物品定义_桥接(数据根, 物品名) : null;
    const 定义 = cloneJsonValue(命中?.定义 || {}, {});
    const 货币 = 读取物品货币选项_桥接(数据根);
    const 分类 = 规范化物品定义分类_桥接(命中?.分类 || 读取物品定义显式分类_桥接(定义, '剧情杂物'), '剧情杂物');
    const 扁平 = (对象, 前缀 = '') => Object.entries(对象 && typeof 对象 === 'object' ? 对象 : {}).flatMap(([键, 值]) => 值 && typeof 值 === 'object' && !Array.isArray(值) ? 扁平(值, `${前缀}${键}.`) : [[`${前缀}${键}`, 格式化物品字段值(值)]]);
    const 技能表 = 定义.附带技能 || 定义.装备技能 || {};
    return {
      旧名: 命中 ? 物品名 : '',
      字段: {
        名称: 命中 ? 物品名 : '', 物品分类: 分类, 品质: 规范化物品经济品质_桥接(定义.品质, 物品名, 分类) || '普通', 基础价格: toNumber(定义.基础价格, 1) || 1,
        默认货币: toText(定义.默认货币, 货币[0] || ''), 描述: toText(定义.描述, ''), 阶位: toNumber(定义.阶位, 0), 魂导等级: 读取魂导等级_桥接(定义),
        魂灵品质: normalizeSoulSpiritQuality(定义.魂灵品质 || ''), 表象名称: toText(定义.表象名称, ''), 标准物种: toText(定义.标准物种, ''), 年限: toNumber(定义.年限, 0),
        装备槽位: toText(定义.装备槽位, '无'), 基础耐久: toNumber(定义.基础耐久, 0), 图纸目标: toText(定义.图纸目标, ''), 材料: 格式化物品结构字段值(定义.材料),
        获取条件: 格式化物品结构字段值(定义.获取条件), 研读条件: 格式化物品结构字段值(定义.研读条件), 解锁内容: 格式化物品结构字段值(定义.解锁内容),
      },
      属性加成: 扁平(定义.属性加成),
      加成方向: Array.isArray(定义.加成方向) ? 定义.加成方向.slice() : [],
      使用效果: Array.isArray(定义.使用效果) ? cloneJsonValue(定义.使用效果, []) : [],
      副作用列表: Array.isArray(定义.副作用列表) ? cloneJsonValue(定义.副作用列表, []) : [],
      技能: Object.entries(技能表 && typeof 技能表 === 'object' ? 技能表 : {}).map(([键, 技能]) => ({ 键, 魂技名: toText(技能 && 技能.魂技名, 键) })),
    };
  }
  // 草稿字段决定显示哪些模块（同原项目编辑器的判定）
  function 读取物品定义形态_桥接(草稿 = {}) {
    const 字段 = 草稿.字段 || {}, 物品名 = toText(字段.名称, '');
    const 分类 = 规范化物品定义分类_桥接(字段.物品分类, '剧情杂物');
    const 定义 = { 魂导等级: toNumber(字段.魂导等级, 0), 装备槽位: toText(字段.装备槽位, '无'), 物品分类: 分类 };
    const 是魂导器 = 读取魂导等级_桥接(定义) > 0 && !判断一次性魂导道具_桥接(物品名, 定义);
    return {
      分类, 是装备: 判断物品为装备_桥接(物品名, 定义), 是魂导器, 是常规装备: 判断常规装备定义_桥接(分类, 是魂导器, 定义),
      是魂骨: 分类 === '魂骨', 是消耗: 可使用物品分类集合_桥接.has(分类), 是锻造: 分类 === '锻造金属', 是魂灵: 分类 === '魂灵',
      是设计图纸: 分类 === '设计图纸', 是修炼秘籍: 分类 === '修炼秘籍',
    };
  }
  function 读取物品定义选项_桥接(数据根 = {}) {
    return {
      分类: 物品定义分类列表_桥接.slice(), 品质: 物品品质选项_桥接.slice(), 货币: 读取物品货币选项_桥接(数据根), 槽位: 物品装备槽位选项_桥接.slice(),
      方向: 装备加成方向选项_桥接.slice(), 属性: 物品属性选项_桥接.slice(), 魂灵品质: 魂灵品质选项_桥接.slice(), 原型: 读取技能设计台原型名称列表(),
    };
  }

  function 迁移物品名称引用(数据根 = {}, 旧名 = '', 新名 = '') {
    if (!旧名 || !新名 || 旧名 === 新名) return;
    const 替换名称字段 = 对象 => {
      if (!对象 || typeof 对象 !== 'object') return;
      Object.values(对象).forEach(值 => {
        if (!值 || typeof 值 !== 'object') return;
        if (toText(值.名称, '') === 旧名) 值.名称 = 新名;
        替换名称字段(值);
      });
    };
    safeEntries(数据根.char).forEach(([, 角色数据]) => {
      if (!角色数据 || typeof 角色数据 !== 'object') return;
      if (角色数据.背包 && typeof 角色数据.背包 === 'object' && 角色数据.背包[旧名]) {
        const 旧实例 = cloneJsonValue(角色数据.背包[旧名], {});
        const 新实例 = 角色数据.背包[新名] && typeof 角色数据.背包[新名] === 'object' ? 角色数据.背包[新名] : null;
        if (新实例) {
          新实例.数量 = Math.max(1, toNumber(新实例.数量, 0) + toNumber(旧实例.数量, 1));
          Object.entries(旧实例).forEach(([键, 值]) => {
            if (键 !== '数量' && 新实例[键] === undefined) 新实例[键] = cloneJsonValue(值, 值);
          });
        } else {
          角色数据.背包[新名] = 旧实例;
        }
        delete 角色数据.背包[旧名];
      }
      替换名称字段(角色数据.装备);
      替换名称字段(角色数据.魂骨);
    });
  }

