    const 新版本列表 = 原版本列表
      .filter(版本 => 规范化冷归档版本楼层_桥接(版本) <= 当前楼层)
      .sort((左, 右) => 规范化冷归档版本楼层_桥接(左) - 规范化冷归档版本楼层_桥接(右));
