  function 收集AI维护差异路径(previousValue, nextValue, basePath = [], result = []) {
    if (JSON.stringify(previousValue) === JSON.stringify(nextValue)) return result;
    const prevIsObject = previousValue && typeof previousValue === 'object';
    const nextIsObject = nextValue && typeof nextValue === 'object';
    if (!prevIsObject || !nextIsObject || Array.isArray(previousValue) || Array.isArray(nextValue)) {
      result.push(basePath.slice());
      return result;
    }
    const keys = new Set([...Object.keys(previousValue), ...Object.keys(nextValue)]);
    keys.forEach(key => {
      收集AI维护差异路径(previousValue[key], nextValue[key], [...basePath, key], result);
    });
    return result;
  }










  function 合并AI维护角色实例底稿_桥接(底稿值, 更新值) {
    if (!isPlainObjectValue(底稿值) || !isPlainObjectValue(更新值)) return cloneJsonValue(更新值, 更新值);
    const 结果 = cloneJsonValue(底稿值, {});
    safeEntries(更新值).forEach(([键, 值]) => {
      结果[键] = isPlainObjectValue(结果[键]) && isPlainObjectValue(值)
        ? 合并AI维护角色实例底稿_桥接(结果[键], 值)
        : cloneJsonValue(值, 值);
    });
    return 结果;
  }





  function formatAge(age) {
    const value = toNumber(age, 0);
    if (value >= 100000) return `${(value / 10000).toFixed(value % 10000 === 0 ? 0 : 1)}万年`;
    if (value >= 10000) return `${(value / 10000).toFixed(value % 10000 === 0 ? 0 : 1)}万年`;
    if (value > 0) return `${formatNumber(value)}年`;
    return '未定';
  }


  function getRingColorKey(color = '') {
    return RING_COLOR_ALIAS_MAP[toText(color, '').trim()] || '';
  }

  function resolveRingTier(color, age, options = {}) {
    const key = getRingColorKey(color);
    const years = toNumber(age, NaN);
    const forceGold = !!(options && options.forceGold);

    if (forceGold) return 'gold';
    if (key) return key;

    if (Number.isFinite(years) && years > 0) {
      if (years >= 200000) return 'orangegold';
      if (years >= 100000) return 'red';
      if (years >= 10000) return 'black';
      if (years >= 1000) return 'purple';
      if (years >= 100) return 'yellow';
      return 'white';
    }
    return 'white';
  }

  function mapRingClass(color, age, options = {}) {
    return `ring-${resolveRingTier(color, age, options)}`;
  }

  function getRingDisplayColorLabel(color, age, options = {}) {
    const directKey = getRingColorKey(color);
    if (directKey && RING_COLOR_META[directKey]) return RING_COLOR_META[directKey].label;
    const tier = resolveRingTier(color, age, options);
    return RING_COLOR_META[tier] ? RING_COLOR_META[tier].label : normalizeSkillUiText(color, '未定');
  }

  function ringGlyph(color, index, age, options = {}) {
    const tier = resolveRingTier(color, age, options);
    const directKey = getRingColorKey(color);
    const resolvedKey = directKey || tier;
    return (RING_COLOR_META[resolvedKey] && RING_COLOR_META[resolvedKey].glyph) || String(index || '环');
  }

  function getMvuHost() {
    const candidates = [];
    const bridgedHost = ensureBridgedMvuHost();
    if (bridgedHost) candidates.push(bridgedHost);
    try {
      if (window.Mvu) candidates.push(window.Mvu);
    } catch (err) {}
    try {
      if (window.top && window.top !== window && window.top.Mvu) candidates.push(window.top.Mvu);
    } catch (err) {}
    try {
      if (typeof Mvu !== 'undefined' && Mvu) candidates.push(Mvu);
    } catch (err) {}
    return candidates.find(item => item) || null;
  }

  function collectMvuProviderCandidates() {
    const providers = [];
    const seen = new Set();
    const pushProvider = (label, candidate) => {
      if (!candidate || (typeof candidate !== 'object' && typeof candidate !== 'function')) return;
      if (seen.has(candidate)) return;
      const hasRead =
        typeof candidate.getAllVariables === 'function' ||
        typeof candidate.getVariables === 'function' ||
        typeof candidate.getMvuData === 'function';
      const hasWrite =
        typeof candidate.replaceVariables === 'function' || typeof candidate.replaceMvuData === 'function';
      if (!hasRead || !hasWrite) return;
      seen.add(candidate);
      providers.push({ label, candidate });
    };

    try {
      pushProvider('当前窗口', window);
    } catch (err) {}
    try {
      if (window.parent && window.parent !== window) pushProvider('父窗口', window.parent);
    } catch (err) {}
    try {
      if (window.top && window.top !== window) pushProvider('顶层窗口', window.top);
    } catch (err) {}
    try {
      Array.from(window.frames || []).forEach((frame, index) => {
        const frameName = String(frame?.name || `frame_${index}`).trim() || `frame_${index}`;
        pushProvider(`子框架:${frameName}`, frame);
      });
    } catch (err) {}

    return providers;
  }

  function buildBridgedMvuHost(providerInfo) {
    const provider = providerInfo && providerInfo.candidate;
    if (!provider) return null;
    return {
      __bridgeSource: String(providerInfo.label || '').trim() || '未知来源',
      getAllVariables(...args) {
        if (typeof provider.getAllVariables === 'function') return provider.getAllVariables(...args);
        if (typeof provider.getVariables === 'function') return provider.getVariables(...args);
        if (typeof provider.getMvuData === 'function') return provider.getMvuData(...args);
        return null;
      },
      getMvuData(options = {}) {
        if (typeof provider.getMvuData === 'function') return provider.getMvuData(options);
        if (typeof provider.getVariables === 'function') return provider.getVariables(options);
        if (typeof provider.getAllVariables === 'function') return provider.getAllVariables(options);
        return null;
      },
      getVariables(options = {}) {
        if (typeof provider.getVariables === 'function') return provider.getVariables(options);
        if (typeof provider.getMvuData === 'function') return provider.getMvuData(options);
        if (typeof provider.getAllVariables === 'function') return provider.getAllVariables(options);
        return null;
      },
      replaceMvuData(nextValue, options = {}) {
        if (typeof provider.replaceMvuData === 'function') return provider.replaceMvuData(nextValue, options);
        if (typeof provider.replaceVariables === 'function') return provider.replaceVariables(nextValue, options);
        throw new Error('mvu_replace_unavailable');
      },
      replaceVariables(nextValue, options = {}) {
        if (typeof provider.replaceVariables === 'function') return provider.replaceVariables(nextValue, options);
        if (typeof provider.replaceMvuData === 'function') return provider.replaceMvuData(nextValue, options);
        throw new Error('mvu_replace_unavailable');
      },
    };
  }

  function ensureBridgedMvuHost() {
    const existingWindowHost = (() => {
      try {
        return window.Mvu && typeof window.Mvu === 'object' ? window.Mvu : null;
      } catch (err) {
        return null;
      }
    })();
    const existingHasRead =
      existingWindowHost &&
      (typeof existingWindowHost.getAllVariables === 'function' ||
        typeof existingWindowHost.getVariables === 'function' ||
        typeof existingWindowHost.getMvuData === 'function');
    const existingHasWrite =
      existingWindowHost &&
      (typeof existingWindowHost.replaceMvuData === 'function' ||
        typeof existingWindowHost.replaceVariables === 'function');
    if (existingHasRead && existingHasWrite) {
      __mvuBridgeRoot.__LWCS_BRIDGED_MVU_HOST__ = existingWindowHost;
      __mvuBridgeRoot.__LWCS_BRIDGED_MVU_HOST_SOURCE__ = String(existingWindowHost.__bridgeSource || '原生Mvu');
      return existingWindowHost;
    }

    const cachedHost =
      __mvuBridgeRoot.__LWCS_BRIDGED_MVU_HOST__ && typeof __mvuBridgeRoot.__LWCS_BRIDGED_MVU_HOST__ === 'object'
        ? __mvuBridgeRoot.__LWCS_BRIDGED_MVU_HOST__
        : null;
    if (cachedHost) return cachedHost;

    const providerInfo = collectMvuProviderCandidates()[0] || null;
    if (!providerInfo) return null;
    const bridgedHost = buildBridgedMvuHost(providerInfo);
    if (!bridgedHost) return null;
    __mvuBridgeRoot.__LWCS_BRIDGED_MVU_HOST__ = bridgedHost;
    __mvuBridgeRoot.__LWCS_BRIDGED_MVU_HOST_SOURCE__ = bridgedHost.__bridgeSource || providerInfo.label || '未知来源';
    try {
      if (!window.Mvu || typeof window.Mvu !== 'object') window.Mvu = bridgedHost;
    } catch (err) {}
    try {
      if (typeof window.getAllVariables !== 'function') {
        window.getAllVariables = (...args) => bridgedHost.getAllVariables(...args);
      }
    } catch (err) {}
    return bridgedHost;
  }

  async function waitForMvuReady() {
    if (ensureBridgedMvuHost()) return;
    try {
      if (typeof waitGlobalInitialized === 'function') {
        await waitGlobalInitialized('Mvu');
        return;
      }
    } catch (err) {}
    try {
      if (window.top && window.top !== window && typeof window.top.waitGlobalInitialized === 'function') {
        await window.top.waitGlobalInitialized('Mvu');
        return;
      }
    } catch (err) {}
  }

  function buildRecentMessageIdCandidates(depth = MVU_RECENT_MESSAGE_SCAN_DEPTH) {
    const ids = ['latest'];
    for (let index = 1; index <= Math.max(1, depth); index += 1) {
      ids.push(-index);
    }
    return ids;
  }

  async function scanRecentMessageVariablesWithReaders(readers = [], options = {}) {
    const depth = toNumber(options && options.depth, MVU_RECENT_MESSAGE_SCAN_DEPTH);
    const messageIds = buildRecentMessageIdCandidates(depth);
    const 使用最近有效快照 = options?.使用最近有效快照 === true;
    let fallbackVars = null;
    let fallbackMessageId = 'latest';
    let bestVars = null;
    let bestMessageId = 'latest';
    let bestScore = -Infinity;

    for (const messageId of messageIds) {
      for (const reader of readers) {
        if (typeof reader !== 'function') continue;
        try {
          const vars = await reader(messageId);
          if (!vars || typeof vars !== 'object') continue;
          if (!fallbackVars) {
            fallbackVars = vars;
            fallbackMessageId = messageId;
          }
          const rootData = resolveRootData(vars);
          if (使用最近有效快照 && rootData && typeof rootData === 'object') {
            return { vars, messageId };
          }
          const nextScore = scoreRootDataCandidate(rootData);
          if (nextScore > bestScore) {
            bestScore = nextScore;
            bestVars = vars;
            bestMessageId = messageId;
          }
        } catch (err) {}
      }
    }

    return {
      vars: bestVars || fallbackVars,
      messageId: bestVars ? bestMessageId : fallbackMessageId,
    };
  }

  async function getLatestMessageVariablesFallback() {
    try {
      if (!当前为TauriTavern环境_桥接() && window.TavernHelper && typeof window.TavernHelper.getVariables === 'function') {
        const 当前楼层 = 读取当前聊天消息编号_桥接();
        for (const 消息编号 of 当前楼层 === null ? ['latest'] : [当前楼层, 'latest']) {
          const 变量 = await Promise.resolve(
            window.TavernHelper.getVariables({ type: 'message', message_id: 消息编号 }),
          );
          if (变量 && typeof 变量 === 'object' && resolveRootData(变量)) return 变量;
        }
      }
    } catch (err) {}
    return null;
  }

  function 读取当前聊天消息编号_桥接() {
    const 候选窗口 = [];
    const 添加窗口 = 候选 => {
      if (候选 && !候选窗口.includes(候选)) 候选窗口.push(候选);
    };
    try { 添加窗口(window); } catch (err) {}
    try { 添加窗口(window.parent); } catch (err) {}
    try { 添加窗口(window.top); } catch (err) {}
    for (const 候选 of 候选窗口) {
      try {
        const 上下文 = typeof 候选.SillyTavern?.getContext === 'function' ? 候选.SillyTavern.getContext() : null;
        const 聊天 = Array.isArray(上下文?.chat) ? 上下文.chat : null;
        if (!聊天?.length) continue;
        const 末条 = 聊天[聊天.length - 1];
        const 消息编号 = Number(末条?.message_id ?? 末条?.id ?? 聊天.length - 1);
        if (Number.isFinite(消息编号)) return Math.trunc(消息编号);
      } catch (err) {}
    }
    return null;
  }

  async function getAllVariablesSafe() {
    const latest = await getLatestVariablesFast();
    if (latest) return latest;
    return await getLatestMessageVariablesFallback();
  }

  async function getLatestVariablesFast() {
    const host = getMvuHost();
    const 当前楼层 = 读取当前聊天消息编号_桥接();
    const 读取选项 = [
      ...(当前楼层 === null ? [] : [{ type: 'message', message_id: 当前楼层 }]),
      { type: 'chat' },
      { type: 'message', message_id: 'latest' },
    ];
    if (host && typeof host.getMvuDataAsync === 'function') {
      try {
        const vars = await host.getMvuDataAsync(读取选项[0]);
        if (vars && typeof vars === 'object' && resolveRootData(vars)) return vars;
      } catch (err) {}
    }
    if (host && typeof host.getMvuData === 'function') {
      for (const 选项 of 读取选项) {
        try {
          const vars = await Promise.resolve(host.getMvuData(选项));
          if (vars && typeof vars === 'object' && resolveRootData(vars)) return vars;
        } catch (err) {}
      }
    }
    if (!当前为TauriTavern环境_桥接() && window.TavernHelper && typeof window.TavernHelper.getVariables === 'function') {
      for (const 选项 of 读取选项) {
        if (选项.type !== 'message') continue;
        try {
          const vars = await Promise.resolve(window.TavernHelper.getVariables(选项));
          if (vars && typeof vars === 'object' && resolveRootData(vars)) return vars;
        } catch (err) {}
      }
    }
    if (host && typeof host.getAllVariables === 'function') {
      try {
        const vars = await Promise.resolve(host.getAllVariables());
        if (vars && typeof vars === 'object' && resolveRootData(vars)) return vars;
      } catch (err) {}
    }
    return null;
  }

  function getSharedMvuRefreshHub() {
    const hubKey = '__dragonUiSharedMvuRefreshHub';
    const existingHub = window[hubKey];
    const isMainRefreshHub = !!(
      existingHub
      && typeof existingHub.subscribe === 'function'
      && typeof existingHub.trigger === 'function'
      && (
        existingHub.owner === 'mvu_logic_bridge'
        || (
          existingHub.runtime
          && typeof existingHub.requestRecovery === 'function'
          && typeof existingHub.markVariableUpdateEnded === 'function'
        )
      )
    );
    if (isMainRefreshHub) {
      try { if (!existingHub.owner) existingHub.owner = 'mvu_logic_bridge'; } catch (_) {}
      return existingHub;
    }
    if (existingHub && typeof existingHub.stopBindings === 'function') {
      try { existingHub.stopBindings(); } catch (_) {}
    }

    const subscribers = new Map();
    const POLL_KEY = '__dragonUiSharedRefreshPollTimer';
    const CHAT_CONTEXT_POLL_KEY = '__dragonUiSharedChatContextPollTimer';
    const POLL_VIS_KEY = '__dragonUiSharedRefreshPollVisibilityBound';
    const POLL_FOCUS_KEY = '__dragonUiSharedRefreshPollFocusBound';
    const MVU_QUIET_WINDOW_MS = 150;
    let bindingsReady = false;
    let running = false;
    let pending = false;
    let lastTriggerArgs = [];
    let lastChatContextSignature = '';
    let revision = 0;
    let quietTimer = 0;
    let variableUpdateActive = false;
    let latestVariables = null;
    let latestVariableEventArgs = [];

    const 读取刷新事件变量载荷 = args => {
      for (const item of Array.isArray(args) ? args : []) {
        if (!item || typeof item !== 'object') continue;
        if (resolveRootData(item)) return item;
        const candidates = [item.detail, item.data, item.payload, item.variables, item.state, item.mvu];
        for (const candidate of candidates) {
          if (candidate && typeof candidate === 'object' && resolveRootData(candidate)) return candidate;
        }
      }
      return null;
    };

    const getChatContextSignature = () => {
      const meta = getCurrentChatContextMeta();
      return [
        toText(meta.characterId, '').trim(),
        toText(meta.groupId, '').trim(),
        toText(meta.chatId, '').trim(),
        toText(meta.name1, '').trim(),
        toText(meta.name2, '').trim(),
      ].join('||');
    };

    const clearQuietTimer = () => {
      if (!quietTimer) return;
      window.clearTimeout(quietTimer);
      quietTimer = 0;
    };

    const schedulePendingDispatch = () => {
      const runner = () => hub.dispatch(...lastTriggerArgs);
      if (typeof queueMicrotask === 'function') {
        queueMicrotask(runner);
        return;
      }
      Promise.resolve().then(runner);
    };

    const hub = {
      owner: 'mvu_logic_bridge',
      contractVersion: 1,

      runtime: {
        get revision() {
          return revision;
        },
        get variableUpdateActive() {
          return variableUpdateActive;
        },
        get latestVariables() {
          return latestVariables;
        },
      },

      async getAllVariables() {
        return await getAllVariablesSafe();
      },

      async dispatch(meta = {}, ...args) {
        const normalizedMeta = meta && typeof meta === 'object' ? meta : { source: 'manual' };
        const expectedRevision = Number.isFinite(normalizedMeta.revision) ? normalizedMeta.revision : revision;
        if (expectedRevision !== revision) return;
        const expectedChatSignature = toText(normalizedMeta.chatSignature, '');
        if (expectedChatSignature && expectedChatSignature !== getChatContextSignature()) return;
        lastTriggerArgs = [normalizedMeta, ...args];
        if (running) {
          pending = true;
          return;
        }
        running = true;
        try {
          const 事件变量 = normalizedMeta.vars || 读取刷新事件变量载荷(args) || latestVariables;
          let vars = 事件变量 || (normalizedMeta.recovery ? await getAllVariablesSafe() : await getLatestVariablesFast());
          if (!vars && !normalizedMeta.recovery) vars = await getAllVariablesSafe();
          if (!vars) return;
          const entries = Array.from(subscribers.entries());
          for (const [subscriberId, subscriber] of entries) {
            try {
              await Promise.resolve(subscriber.handler(vars, normalizedMeta, ...args));
            } catch (error) {
              console.warn(`[DragonUI] MVU shared refresh subscriber failed: ${subscriberId}`, error);
            }
          }
        } finally {
          running = false;
          if (pending) {
            pending = false;
            schedulePendingDispatch();
          }
        }
      },

      trigger(meta = {}, ...args) {
        return hub.dispatch(meta, ...args);
      },

      markVariableUpdateStarted(...args) {
        variableUpdateActive = true;
        latestVariables = null;
        latestVariableEventArgs = args;
        clearQuietTimer();
      },

      markVariableUpdateEnded(...args) {
        variableUpdateActive = false;
        latestVariables = 读取刷新事件变量载荷(args);
        latestVariableEventArgs = args;
        clearQuietTimer();
        const scheduledRevision = revision;
        const scheduledChatSignature = getChatContextSignature();
        quietTimer = window.setTimeout(() => {
          quietTimer = 0;
          if (scheduledRevision !== revision || scheduledChatSignature !== getChatContextSignature()) return;
          hub.dispatch(
            {
              source: 'variable_update_ended',
              eventKey: 'VARIABLE_UPDATE_ENDED',
              revision: scheduledRevision,
              chatSignature: scheduledChatSignature,
              vars: latestVariables,
            },
            ...latestVariableEventArgs,
          );
        }, MVU_QUIET_WINDOW_MS);
      },

      requestRecovery(source, args = [], delay = 0) {
        revision += 1;
        variableUpdateActive = false;
        latestVariables = null;
        latestVariableEventArgs = [];
        clearQuietTimer();
        const scheduledRevision = revision;
        const scheduledChatSignature = getChatContextSignature();
        window.setTimeout(() => {
          if (scheduledRevision !== revision || scheduledChatSignature !== getChatContextSignature()) return;
          hub.dispatch(
            {
              source,
              recovery: true,
              force: true,
              revision: scheduledRevision,
              chatSignature: scheduledChatSignature,
            },
            ...(Array.isArray(args) ? args : []),
          );
        }, Math.max(0, Number(delay) || 0));
      },

      ensureBindings() {
        if (bindingsReady) return;
        bindingsReady = true;

        const host = getMvuHost();
        const variableUpdateStartedEvent =
          host?.events?.VARIABLE_UPDATE_STARTED || window.Mvu?.events?.VARIABLE_UPDATE_STARTED || 'mag_variable_update_started';
        const variableUpdateEndedEvent =
          host?.events?.VARIABLE_UPDATE_ENDED || window.Mvu?.events?.VARIABLE_UPDATE_ENDED || 'mag_variable_update_ended';
        const commitFinishedEvent =
          host?.events?.COMMIT_FINISHED || window.Mvu?.events?.COMMIT_FINISHED || 'lwcs_mvu_commit_finished';
        const eventOnFn =
          typeof __mvuBridgeRoot.eventOn === 'function'
            ? __mvuBridgeRoot.eventOn.bind(__mvuBridgeRoot)
            : typeof window.eventOn === 'function'
              ? window.eventOn.bind(window)
              : null;
        let bound = false;
        let chatChangedBound = false;
        const startFromEvent = (...args) => hub.markVariableUpdateStarted(...args);
        const endFromEvent = (...args) => hub.markVariableUpdateEnded(...args);
        const commitFinishedFromEvent = (...args) => {
          const 载荷 = args.find(item => item && typeof item === 'object') || null;
          if (载荷?.status && 载荷.status !== 'committed') return;
          hub.requestRecovery('mvu_commit_finished', args, 0);
        };
        const bindMvuEvent = (target, method, eventName, handler) => {
          if (!target || !eventName || typeof target[method] !== 'function') return false;
          try {
            target[method](eventName, handler);
            return true;
          } catch (err) {
            return false;
          }
        };
        const bindSillyTavernEventSource = () => {
          let context = null;
          try {
            context = typeof window.SillyTavern?.getContext === 'function' ? window.SillyTavern.getContext() : null;
          } catch (err) {}
          const eventSource = context?.eventSource;
          if (!eventSource || typeof eventSource.on !== 'function') return false;
          const eventTypes = context?.eventTypes || {};
          let hasBound = false;
          [
            'MESSAGE_SENT',
            'MESSAGE_UPDATED',
            'GENERATION_ENDED',
            'CHAT_CHANGED',
            'MESSAGE_DELETED',
            'MESSAGE_SWIPED',
            'MESSAGE_EDITED',
          ].forEach(eventKey => {
            const sillyEventName = eventTypes[eventKey] || eventKey;
            if (!sillyEventName) return;
            try {
              eventSource.on(sillyEventName, (...args) => {
                if (eventKey === 'MESSAGE_SENT' || eventKey === 'MESSAGE_UPDATED' || eventKey === 'GENERATION_ENDED') return;
                hub.requestRecovery(`silly_event:${eventKey}`, args, eventKey === 'CHAT_CHANGED' ? 0 : 80);
              });
              if (eventKey === 'CHAT_CHANGED') chatChangedBound = true;
              hasBound = true;
            } catch (err) {}
          });
          if (variableUpdateStartedEvent) {
            try {
              eventSource.on(variableUpdateStartedEvent, startFromEvent);
              hasBound = true;
            } catch (err) {}
          }
          if (variableUpdateEndedEvent) {
            try {
              eventSource.on(variableUpdateEndedEvent, endFromEvent);
              hasBound = true;
            } catch (err) {}
          }
          if (commitFinishedEvent) {
            try {
              eventSource.on(commitFinishedEvent, commitFinishedFromEvent);
              hasBound = true;
            } catch (err) {}
          }
          return hasBound;
        };

        if (eventOnFn) {
          try {
            if (variableUpdateStartedEvent) eventOnFn(variableUpdateStartedEvent, startFromEvent);
            if (variableUpdateEndedEvent) eventOnFn(variableUpdateEndedEvent, endFromEvent);
            if (commitFinishedEvent) eventOnFn(commitFinishedEvent, commitFinishedFromEvent);
            bound = true;
          } catch (err) {}
        }

        if (bindMvuEvent(host, 'on', variableUpdateStartedEvent, startFromEvent)) bound = true;
        if (bindMvuEvent(host, 'on', variableUpdateEndedEvent, endFromEvent)) bound = true;
        if (bindMvuEvent(host, 'on', commitFinishedEvent, commitFinishedFromEvent)) bound = true;
        if (bindMvuEvent(host, 'addEventListener', variableUpdateStartedEvent, startFromEvent)) bound = true;
        if (bindMvuEvent(host, 'addEventListener', variableUpdateEndedEvent, endFromEvent)) bound = true;
        if (bindMvuEvent(host, 'addEventListener', commitFinishedEvent, commitFinishedFromEvent)) bound = true;

        [variableUpdateStartedEvent, variableUpdateEndedEvent, commitFinishedEvent].forEach(eventName => {
          if (!eventName) return;
          const handler = eventName === variableUpdateStartedEvent
            ? startFromEvent
            : eventName === variableUpdateEndedEvent
              ? endFromEvent
              : commitFinishedFromEvent;
          try {
            window.addEventListener(eventName, handler);
            bound = true;
          } catch (err) {}
          try {
            if (window.top && window.top !== window && typeof window.top.addEventListener === 'function') {
              window.top.addEventListener(eventName, handler);
              bound = true;
            }
          } catch (err) {}
        });

        if (bindSillyTavernEventSource()) bound = true;

        if (window[POLL_KEY]) {
          try {
            window.clearInterval(window[POLL_KEY]);
          } catch (err) {}
          window[POLL_KEY] = 0;
        }

        lastChatContextSignature = getChatContextSignature();
        if (chatChangedBound) {
          if (window[CHAT_CONTEXT_POLL_KEY]) {
            try {
              window.clearInterval(window[CHAT_CONTEXT_POLL_KEY]);
            } catch (err) {}
            window[CHAT_CONTEXT_POLL_KEY] = 0;
          }
        } else if (!window[CHAT_CONTEXT_POLL_KEY]) {
          window[CHAT_CONTEXT_POLL_KEY] = window.setInterval(() => {
            if (document.visibilityState === 'hidden') return;
            const nextSignature = getChatContextSignature();
            if (nextSignature === lastChatContextSignature) return;
            lastChatContextSignature = nextSignature;
            try {
              if (!window.__MVU_MANUAL_CHAR_SET) {
                setPreferredActiveCharacterName('');
              }
            } catch (err) {}
            hub.requestRecovery('chat_context', [], 0);
          }, 1000);
        }

        if (!window[POLL_VIS_KEY]) {
          document.addEventListener('visibilitychange', () => {
            if (document.visibilityState === 'visible') hub.requestRecovery('visibility', [], 80);
          });
          window[POLL_VIS_KEY] = true;
        }

        if (!window[POLL_FOCUS_KEY]) {
          window.addEventListener('focus', () => {
            hub.requestRecovery('focus', [], 80);
          });
          window[POLL_FOCUS_KEY] = true;
        }

      },

      subscribe(subscriberId, handler, options = {}) {
        if (!subscriberId || typeof handler !== 'function') return () => {};
        subscribers.set(subscriberId, { handler });
        hub.ensureBindings();
        if (options.immediate !== false) {
          hub.requestRecovery(`subscribe:${subscriberId}`, [], 0);
        }
        return () => {
          subscribers.delete(subscriberId);
        };
      },
    };

    window[hubKey] = hub;
    return hub;
  }

  function bindMvuUpdates(handler, options = {}) {
    const hub = getSharedMvuRefreshHub();
    return hub.subscribe('dragon-ui-main', async (vars, ...args) => {
      try {
        await Promise.resolve(handler(vars, ...args));
      } catch (error) {
        console.warn('[DragonUI] MVU 实时刷新执行失败', error);
      }
    }, options);
  }

  function resolveRootData(vars) {
    if (!vars || typeof vars !== 'object') return null;
    const candidates = [vars, vars.data, vars.variables, vars.payload, vars.state, vars.mvu, vars.root];
    for (const item of candidates) {
      if (!item || typeof item !== 'object') continue;
      if (
        item.stat_data &&
        typeof item.stat_data === 'object' &&
        (item.stat_data.char || item.stat_data.world || item.stat_data.sys)
      ) {
        return item.stat_data;
      }
      if (item.char || item.world || item.sys || item.org) {
        return item;
      }
    }
    return null;
  }

  function buildEffectiveSd(rawSd) {
    if (!rawSd || typeof rawSd !== 'object') return { rootData: null, rawData: null };

    const rootData = {
      sys: rawSd.sys || {},
      world: rawSd.world || {},
      org: rawSd.org || {},
      char: rawSd.char || {},
      物品: rawSd.物品 || {},
    };
    const currentPlayerName = toText(deepGet(rootData, 'sys.玩家名', ''), '').trim();
    if (isInvalidRuntimePlayerName(currentPlayerName)) {
      const contextMeta = getCurrentChatContextMeta();
      const preferredName = getPreferredActiveCharacterName();
      const battlePlayerName = getBattlePlayerNameFromRootData(rootData);
      const candidates = [
        battlePlayerName,
        preferredName,
        toText(contextMeta.name1, '').trim(),
        toText(contextMeta.name2, '').trim(),
      ].filter(Boolean);
      const repairedPlayerName = candidates.find(
        name => rootData.char && typeof rootData.char === 'object' && rootData.char[name],
      );
      if (repairedPlayerName) {
        if (!rootData.sys || typeof rootData.sys !== 'object') rootData.sys = {};
        rootData.sys.玩家名 = repairedPlayerName;
      }
    }
    return {
      rootData,
      rawData: rawSd,
    };
  }

  function getCurrentChatContextMeta() {
    try {
      const ctx =
        window.SillyTavern && typeof window.SillyTavern.getContext === 'function'
          ? window.SillyTavern.getContext()
          : null;
      if (!ctx || typeof ctx !== 'object') {
        return { name1: '', name2: '', chatId: '', characterId: '', groupId: '' };
      }
      return {
        name1: toText(ctx.name1, '').trim(),
        name2: toText(ctx.name2, '').trim(),
        chatId: toText(ctx.chatId, '').trim(),
        characterId: toText(ctx.characterId, '').trim(),
        groupId: toText(ctx.groupId, '').trim(),
      };
    } catch (err) {
      return { name1: '', name2: '', chatId: '', characterId: '', groupId: '' };
    }
  }

  function hasRootRuntimeSignals(rootData) {
    if (!rootData || typeof rootData !== 'object') return false;
    if (toText(deepGet(rootData, 'sys.玩家名', ''), '').trim()) return true;
    if (safeEntries(deepGet(rootData, 'world.时间线', {})).length) return true;
    if (deepGet(rootData, 'world.偏差值', undefined) !== undefined) return true;
    if (toText(deepGet(rootData, 'world.时间._calendar', deepGet(rootData, 'world.时间.calendar', '')), '').trim())
      return true;
    return false;
  }

  function isRootDataRelevantToCurrentChat(rootData) {
    if (!rootData || typeof rootData !== 'object') return false;
    const chars = rootData.char && typeof rootData.char === 'object' ? rootData.char : {};
    const preferredName = getPreferredActiveCharacterName();
    const sysPlayerName = toText(deepGet(rootData, 'sys.玩家名', ''), '').trim();
    const contextMeta = getCurrentChatContextMeta();
    if (preferredName && chars[preferredName]) return true;
    if (sysPlayerName && chars[sysPlayerName]) return true;
    if (contextMeta.name1 && chars[contextMeta.name1]) return true;
    if (contextMeta.name2 && chars[contextMeta.name2]) return true;
    if (contextMeta.name1 || contextMeta.name2) return false;
    return hasRootRuntimeSignals(rootData);
  }

  function scoreRootDataCandidate(rootData) {
    if (!rootData || typeof rootData !== 'object') return -1;
    const chars = rootData.char && typeof rootData.char === 'object' ? rootData.char : {};
    const contextMeta = getCurrentChatContextMeta();
    let score = 0;
    if (rootData.sys && typeof rootData.sys === 'object') score += 6;
    if (toText(deepGet(rootData, 'sys.玩家名', ''), '').trim()) score += 12;
    if (safeEntries(deepGet(rootData, 'world.时间线', {})).length) score += 5;
    if (deepGet(rootData, 'world.偏差值', undefined) !== undefined) score += 3;
    if (safeEntries(chars).length) score += 1;
    if (contextMeta.name1 && chars[contextMeta.name1]) score += 10;
    if (contextMeta.name2 && chars[contextMeta.name2]) score += 4;
    if (isRootDataRelevantToCurrentChat(rootData)) score += 8;
    return score;
  }

  function getPreferredActiveCharacterName() {
    return toText(preferredActiveCharacterName, '').trim();
  }

  function setPreferredActiveCharacterName(name) {
    preferredActiveCharacterName = toText(name, '').trim();
    try {
      window.__MVU_ACTIVE_CHARACTER__ = preferredActiveCharacterName;
    } catch (_) {}
    return preferredActiveCharacterName;
  }

  function isPlayerCharacterEntry(name, char, playerName = '') {
    const safeName = toText(name, '').trim();
    const safePlayerName = toText(playerName, '').trim();
    return !!safePlayerName && safeName === safePlayerName;
  }

  function isInvalidRuntimePlayerName(name = '') {
    const safeName = toText(name, '').trim();
    return !safeName || ['无名氏', '玩家', '己方', 'Unknown', '未知'].includes(safeName);
  }

  function getBattlePlayerNameFromRootData(rootData = {}) {
    return toText(deepGet(rootData, 'world.战斗.参战者.team_player.0.name', ''), '').trim();
  }

  function resolveEffectivePlayerName(rootData = {}, fallbackActiveName = '') {
    const sysPlayerName = toText(deepGet(rootData, 'sys.玩家名', ''), '').trim();
    if (!isInvalidRuntimePlayerName(sysPlayerName)) return sysPlayerName;
    const battlePlayerName = getBattlePlayerNameFromRootData(rootData);
    if (battlePlayerName) return battlePlayerName;
    return toText(fallbackActiveName, '').trim();
  }


  function getPinnedCharacterOrder(name = '') {
    const safeName = toText(name, '').trim();
    const pinnedNames = [
      ['唐舞麟'],
      ['古月娜', '古月'],
      ['谢邂'],
      ['许小言'],
      ['乐正宇'],
      ['原恩夜辉'],
      ['叶星澜'],
      ['徐笠智'],
      ['舞长空'],
    ];
    for (let index = 0; index < pinnedNames.length; index += 1) {
      if (pinnedNames[index].includes(safeName)) return index + 1;
    }
    return -1;
  }

  function getCharacterDisplayPriority(name, char, options = {}) {
    const { playerName = '', currentName = '' } = options || {};
    const safeName = toText(name, '').trim();
    if (isPlayerCharacterEntry(safeName, char, playerName)) return 0;
    const pinnedOrder = getPinnedCharacterOrder(safeName);
    if (pinnedOrder >= 0) return pinnedOrder;
    if (safeName && safeName === toText(currentName, '').trim()) return 20;
    return 100;
  }

  function sortCharacterEntries(entries, options = {}) {
    return [...(Array.isArray(entries) ? entries : [])].sort((a, b) => {
      const rankDiff =
        getCharacterDisplayPriority(a[0], a[1], options) - getCharacterDisplayPriority(b[0], b[1], options);
      if (rankDiff !== 0) return rankDiff;
      const lvDiff = toNumber(deepGet(b[1], '属性.等级', 0), 0) - toNumber(deepGet(a[1], '属性.等级', 0), 0);
      if (lvDiff !== 0) return lvDiff;
      return toText(a[0], '').localeCompare(toText(b[0], ''), 'zh-Hans-CN', { numeric: true, sensitivity: 'base' });
    });
  }

  function findRealPlayerEntry(charEntries, playerName = '') {
    return (
      sortCharacterEntries(charEntries, { playerName }).find(([name, char]) =>
        isPlayerCharacterEntry(name, char, playerName),
      ) || null
    );
  }

  function resolveActiveCharacter(sd) {
    const chars = sd && sd.char ? sd.char : {};
    const charEntries = safeEntries(chars);
    const preferredName = getPreferredActiveCharacterName();
    const sysPlayerName = resolveEffectivePlayerName(sd || {}, preferredName);
    const contextMeta = getCurrentChatContextMeta();
    const sortedEntries = sortCharacterEntries(charEntries, { playerName: sysPlayerName, currentName: preferredName });
    const realPlayerEntry = findRealPlayerEntry(charEntries, sysPlayerName);

    // 如果有偏好名字并且存在
    if (preferredName && chars[preferredName]) {
      // 如果当前偏好的不是玩家，但宇宙里已经有了真正的玩家，且并非用户显式固定的，就自动退位让贤
      const isPreferredPlayer = isPlayerCharacterEntry(preferredName, chars[preferredName], sysPlayerName);
      if (!isPreferredPlayer && realPlayerEntry && !window.__MVU_MANUAL_CHAR_SET) {
        return realPlayerEntry;
      }
      return [preferredName, chars[preferredName]];
    }

    const namedCandidates = [deepGet(sd, 'sys.玩家名', ''), contextMeta.name1, contextMeta.name2].filter(Boolean);

    for (const name of namedCandidates) {
      if (chars[name]) return [name, chars[name]];
    }

    if (realPlayerEntry) {
      return realPlayerEntry;
    }

    if (!sortedEntries.length) {
      return ['Unknown', {}];
    }

    const pinnedCandidate = sortedEntries.find(([name]) => getPinnedCharacterOrder(name) >= 0);
    if (pinnedCandidate) {
      return pinnedCandidate;
    }

    return sortedEntries[0];
  }

  function isSnapshotPlayerControlled(snapshot) {
    const playerName = resolveEffectivePlayerName(
      deepGet(snapshot, 'rootData', {}),
      toText(snapshot && snapshot.activeName, ''),
    );
    const activeName = toText(snapshot && snapshot.activeName, '').trim();
    return isPlayerCharacterEntry(activeName, deepGet(snapshot, 'activeChar', {}), playerName);
  }

  function formatAppearanceMeta(外貌数据) {
    const data = 外貌数据 && typeof 外貌数据 === 'object' ? 外貌数据 : {};
    const features = Array.isArray(data['特殊特征'])
      ? data['特殊特征']
          .map(item => toText(item, '').trim())
          .filter(Boolean)
          .filter(item => !/^待补全\(/.test(item))
      : [];
    return {
      hairColor: toText(data['发色'], '未设定') || '未设定',
      hairStyle: toText(data['发型'], '未设定') || '未设定',
      eyes: toText(data['瞳色'], '未设定') || '未设定',
      height: toText(data['身高'], '未设定') || '未设定',
      build: toText(data['体型'], '未设定') || '未设定',
      looks: toText(data['长相描述'], '未设定') || '未设定',
      features: features.length ? features.join('、') : '未设定',
    };
  }

  function formatAppearanceText(外貌数据) {
    const meta = formatAppearanceMeta(外貌数据);
    const parts = [meta.hairColor, meta.hairStyle, meta.eyes, meta.height, meta.build]
      .filter(Boolean)
      .filter(item => item !== '未设定');
    const looksText = meta.looks && meta.looks !== '未设定' ? `；长相：${meta.looks}` : '';
    const featureText = meta.features && meta.features !== '未设定' ? `；特征：${meta.features}` : '';
    if (parts.length) return `${parts.join(' / ')}${looksText}${featureText}`;
    if (looksText || featureText) return `${looksText}${featureText}`.replace(/^；/, '');
    return '未设定';
  }

  function normalizeLocationName(sd, rawLoc) {
    const loc = toText(rawLoc, '未知');
    const worldLocations = deepGet(sd, 'world.地点', {});
    if (worldLocations[loc]) return loc;

    const separators = ['·', '｜', '/', '→'];
    for (const separator of separators) {
      if (loc.includes(separator)) {
        const token = loc.split(separator)[0].trim();
        if (worldLocations[token]) return token;
      }
    }

    const fuzzy = safeEntries(worldLocations).find(([name]) => loc.includes(name) || name.includes(loc));
    return fuzzy ? fuzzy[0] : loc;
  }

  function resolveLocationData(sd, rawLoc) {
    const worldLocations = deepGet(sd, 'world.地点', {});
    const exact = toText(rawLoc, '未知');
    if (worldLocations[exact]) return { name: exact, data: worldLocations[exact] };
    const normalized = normalizeLocationName(sd, exact);
    if (worldLocations[normalized]) return { name: normalized, data: worldLocations[normalized] };
    return { name: normalized, data: null };
  }

  function isTodoPlaceholderText(value) {
    return hasUiPlaceholderToken(value);
  }

  function normalizeSkillUiText(value, fallback = '未知') {
    const text = toText(value, '')
      .replace(/\[续台推演\]\s*/g, '')
      .trim();
    if (!text || text === '无' || text === '未生成' || isTodoPlaceholderText(text)) return fallback;
    return text;
  }

  function 格式化技能消耗显示文本_桥接(消耗值, 兜底文本 = '无') {
    if (消耗值 === undefined || 消耗值 === null || 消耗值 === '') return 兜底文本;
    if (typeof 消耗值 !== 'object') return normalizeSkillUiText(消耗值, 兜底文本);
    const 格式化原子值 = 值 => {
      if (值 === undefined || 值 === null || 值 === '') return '';
      if (typeof 值 === 'number') return Number.isFinite(值) ? formatNumber(值) : '';
      if (typeof 值 === 'string') return normalizeSkillUiText(值, '');
      return '';
    };
    const 格式化资源对象 = 资源对象 => {
      if (!资源对象 || typeof 资源对象 !== 'object') return 格式化原子值(资源对象);
      return Object.entries(资源对象)
        .filter(([资源名]) => !['启动', 'upfront', '维持', 'sustain'].includes(String(资源名 || '')))
        .map(([资源名, 数值]) => {
          const 文本 = 格式化原子值(数值);
          return 文本 ? `${资源名}:${文本}` : '';
        })
        .filter(Boolean)
        .join(' | ');
    };
    if (Array.isArray(消耗值)) {
      const 文本 = 消耗值.map(条目 => 格式化技能消耗显示文本_桥接(条目, '')).filter(Boolean).join(' | ');
      return 文本 || 兜底文本;
    }
    const 启动消耗 = 消耗值.启动 || 消耗值.upfront || null;
    const 维持消耗 = 消耗值.维持 || 消耗值.sustain || null;
    const 基础文本 = 格式化资源对象(启动消耗 || 消耗值);
    const 维持文本 = 格式化资源对象(维持消耗);
    const 片段 = [];
    if (基础文本) 片段.push(基础文本);
    if (维持文本) 片段.push(`维持:${维持文本}`);
    return 片段.join(' ') || 兜底文本;
  }

  function summarizeUsageLikeArray(effectArray) {
    const entries = Array.isArray(effectArray) ? effectArray : [];
    const packedNames = entries
      .map(effect => toText(effect && effect['原型'], '').trim())
      .filter(Boolean)
      .filter(name => name !== '系统基础');
    if (packedNames.length) return packedNames.join(' / ');
    const descNames = entries.map(effect => toText(effect && effect['description'], '').trim()).filter(Boolean);
    return descNames.length ? descNames.slice(0, 3).join(' / ') : '未知';
  }

  function summarizeConstructEffectUi(effect) {
    const itemCount = Math.max(1, toNumber(effect && effect['数量'], 1));
    const expiry = resolveExpiryUiText(effect, '');
    const usageSummary = summarizeUsageLikeArray(effect && effect['使用效果']);
    const header = `生成造物×${itemCount}`;
    return [header, expiry ? `有效期:${expiry}` : '', usageSummary !== '未知' ? `使用效果:${usageSummary}` : '']
      .filter(Boolean)
      .join(' / ');
  }


  function summarizeSummonEffectUi(effect) {
    const 单位类型 = normalizeSkillUiText(effect && effect['召唤单位类型'], '魂兽');
    const 名称 = normalizeSkillUiText(effect && effect['召唤物名称'], '召唤物');
    const 数量 = Math.max(1, toNumber(effect && (effect['数量'] ?? effect['召唤数量']), 1));
    const 持续回合 = Math.max(0, toNumber(effect && effect['持续回合'], 0));
    const 行动模式 = normalizeSkillUiText(effect && effect['行动模式'], '');
    const 强度 = Number(effect && effect['强度']);
    const 继承比例 = Math.max(0, Math.min(1, toNumber(effect && effect['继承属性比例'], 0)));
    const 使用继承 = 继承比例 > 0;
    return [
      `召唤${单位类型}【${名称}】×${数量}`,
      行动模式,
      !使用继承 && Number.isFinite(强度) ? `强度:${强度}` : '',
      使用继承 ? `平均继承:${Math.round(继承比例 * 100)}%` : '',
      持续回合 > 0 ? `持续:${持续回合}回合` : '',
    ]
      .filter(Boolean)
      .join(' / ');
  }

  function extractConstructEffectMeta(effectArray) {
    const createEffect = (Array.isArray(effectArray) ? effectArray : []).find(effect => {
      return (
        effect &&
        typeof effect === 'object' &&
        !toText(effect['原型'], '').trim() &&
        Array.isArray(effect['使用效果'])
      );
    });
    if (!createEffect) return null;
    return { summary: summarizeConstructEffectUi(createEffect) };
  }

  const SKILL_DESIGNER_PREVIEW_PREFIX = '技能设计台：';
  const SKILL_SUMMARY_EFFECT_MECHANISM_SET = new Set();
  const SHARED_SKILL_MECHANISM_REGISTRY =
    __mvuBridgeRoot.__LWCS_SKILL_MECHANISM_REGISTRY__ &&
    typeof __mvuBridgeRoot.__LWCS_SKILL_MECHANISM_REGISTRY__ === 'object'
      ? __mvuBridgeRoot.__LWCS_SKILL_MECHANISM_REGISTRY__
      : null;
  const SKILL_DESIGNER_MECHANISM_META = Object.freeze(SHARED_SKILL_MECHANISM_REGISTRY?.机制定义 || {});
  const SKILL_DESIGNER_PROTOTYPE_REGISTRY = Object.freeze(SHARED_SKILL_MECHANISM_REGISTRY?.原型定义 || {});
  const 技能设计台机制抹消可匹配字段表 = Object.freeze(SHARED_SKILL_MECHANISM_REGISTRY?.机制抹消可匹配字段 || {});
  const 技能设计台嵌套效果数组字段表 = Object.freeze(SHARED_SKILL_MECHANISM_REGISTRY?.嵌套效果数组字段 || []);
  const 技能设计台条件分支效果数组字段表 = Object.freeze(SHARED_SKILL_MECHANISM_REGISTRY?.条件分支效果数组字段 || []);
  const 技能设计台效果槽位字段表 = Object.freeze(SHARED_SKILL_MECHANISM_REGISTRY?.技能效果槽位字段 || []);
