      if (SKILL_DESIGNER_CONDITION_BRANCH_RATIO_TYPES.includes(type)) 值控件 = '比例';
      else if (SKILL_DESIGNER_CONDITION_BRANCH_NUMBER_TYPES.includes(type)) 值控件 = '数字';
