      if (数量) 字段['数量'] = 数量 === '全部' ? '全部' : Math.max(1, Math.min(3, parseSkillDesignerIntegerInputValue(数量, 1, 1)));
      const 匹配原型 = normalizeSkillUiText(字段['匹配原型'], '');
