  function clampUnifiedMapCanvas(root = document) {
    if (!document.body || !document.body.classList.contains('mvu-layout-holo')) return;
    const scope = root && typeof root.querySelectorAll === 'function' ? root : document;
    const canvases = scope.querySelectorAll(
      '#mvu-unified-mount .mvu-unified-map-stage .map-canvas.map-canvas-large, #mvu-unified-mount .mvu-holo-detail-stage .map-canvas.map-canvas-large',
    );
    const viewportHeight = Math.max(
      520,
      Number(window.innerHeight) || Number(document.documentElement.clientHeight) || 720,
    );
    canvases.forEach(canvas => {
      if (!(canvas instanceof HTMLElement)) return;
      if (canvas.hasAttribute('data-cabin-plane') || canvas.closest('.dc-native-content')) {
        ['height', 'width', 'min-height', 'max-height', 'aspect-ratio', 'flex-basis'].forEach(属性 => canvas.style.removeProperty(属性));
        return;
      }
      const isDetail = !!canvas.closest('.mvu-holo-detail-stage');
      const 是概览星图 = !isDetail && !!canvas.closest('.mvu-unified-map-stage');
      if (是概览星图) {
        canvas.style.setProperty('height', '100%', 'important');
        canvas.style.setProperty('width', '100%', 'important');
        canvas.style.setProperty('min-height', '0px', 'important');
        canvas.style.setProperty('max-height', 'none', 'important');
        canvas.style.setProperty('aspect-ratio', 'auto', 'important');
        canvas.style.setProperty('flex-basis', 'auto', 'important');
        return;
      }
      const 所属舞台 = canvas.closest('.mvu-unified-map-stage, .mvu-holo-detail-stage');
      const 舞台高度 =
        所属舞台 instanceof HTMLElement
          ? Math.round(所属舞台.getBoundingClientRect().height || 所属舞台.clientHeight || 0)
          : 0;
      const 视口目标 = isDetail ? Math.round(viewportHeight * 0.56) : Math.round(viewportHeight * 0.7);
      const 容器目标 = 舞台高度 > 120 ? Math.max(220, 舞台高度 - (isDetail ? 18 : 20)) : 0;
      const targetHeight = Math.max(isDetail ? 360 : 420, Math.min(isDetail ? 620 : 680, 容器目标 || 视口目标));
      canvas.style.setProperty('height', `${targetHeight}px`, 'important');
      canvas.style.setProperty('width', '100%', 'important');
      canvas.style.setProperty('min-height', '0px', 'important');
      canvas.style.setProperty('max-height', `${targetHeight}px`, 'important');
      canvas.style.setProperty('aspect-ratio', 'auto', 'important');
      canvas.style.setProperty('flex-basis', 'auto', 'important');
    });
  }

  function scheduleUnifiedMapCanvasClamp(root = document) {
    const run = () => clampUnifiedMapCanvas(root);
    if (typeof window.requestAnimationFrame === 'function') {
      window.requestAnimationFrame(() => window.requestAnimationFrame(run));
    } else {
      window.setTimeout(run, 0);
    }
    window.setTimeout(run, 80);
    window.setTimeout(run, 220);
  }

  window.addEventListener('resize', () => scheduleUnifiedMapCanvasClamp());

