    const 选项 = { method: toText(参数.method, ''), listMethods: true };
    const 直达 = 地图.describeTravelToNode(目标, 选项);
    if (直达 && 直达.reasonCode !== 'map_node_unresolved') return { ...直达, mode: 'map', target: 目标, mapNode: 目标 };
