  function getBattleInlineHost() {
    const host = document.getElementById('lwcs-battle-host');
    return host instanceof Element && host.isConnected ? host : null;
  }


  const 召唤夹具名称列表 = Object.freeze([
    '召唤:生成入表',
    '召唤:受击治疗护盾状态',
    '召唤:群体护卫协同自主',
    '召唤:收回死亡精神',
    '召唤:目标池与单体收回',
    '召唤:分身目标隔离',
    '召唤:批量编号重复召唤',
    '召唤:UI预览',
  ]);

  function 构建召唤夹具战斗数据() {
    const 生成单位 = 名称 => ({
      name: 名称,
      type: '强攻系',
      lv: 45,
      hp: 1200,
      hp_max: 1200,
      HP: 1200,
      HP上限: 1200,
      体力: 900,
      体力上限: 900,
      sp: 800,
      sp_max: 800,
      men: 600,
      men_max: 600,
      str: 180,
      def: 120,
      agi: 110,
      状态效果: {},
      持续效果: {},
    });
    const 宿主 = 生成单位('召唤夹具宿主');
    const 敌人 = 生成单位('召唤夹具敌人');
    宿主.状态效果['召唤:预览召唤物'] = {
      类型: 'buff',
      层数: 1,
      duration: 3,
      战斗效果: {},
      召唤物: {
        召唤单位类型: '魂兽',
        召唤物名称: '预览召唤物',
        召唤数量: 1,
        行动模式: '自主行动',
        强度: 1,
      },
    };
    return {
      进行中: true,
      回合: 1,
      战斗类型: '召唤夹具',
      阶段: '宣告阶段',
      参战者: { team_player: [宿主], team_enemy: [敌人] },
    };
  }

  async function 挂载临时召唤夹具战斗UI() {
    if (!await 确保交互模块已加载('战斗模块', 'mountBattleUI')) return null;
    if (typeof window.mountBattleUI !== 'function') {
      throw new Error('战斗模块未就绪');
    }
    const 原战斗UI = window.BattleUI;
    const 容器 = document.createElement('div');
    容器.setAttribute('data-lwcs-summon-fixture-host', '1');
    容器.style.cssText = 'position:fixed;left:-9999px;top:0;width:720px;z-index:-1;pointer-events:none;';
    容器.innerHTML = buildBattleInlineHostMarkup();
    document.body.appendChild(容器);
    const 战斗数据 = 构建召唤夹具战斗数据();
    const 组件 = window.mountBattleUI(容器, {}, { combatData: 战斗数据 });
    await new Promise(resolve => window.setTimeout(resolve, 40));
    return {
      容器,
      组件,
      战斗数据,
      清理() {
        try {
          if (组件 && typeof 组件.destroy === 'function') 组件.destroy();
        } catch (错误) {}
        容器.remove();
        if (原战斗UI !== undefined) window.BattleUI = 原战斗UI;
        else delete window.BattleUI;
      },
    };
  }

  function 归一化召唤夹具名称(名称 = '') {
    return String(名称 || '').replace(/^召唤[:：]/, '').trim();
  }

  function 包装召唤夹具结果(名称, 执行函数) {
    const 日志 = [];
    try {
      const 结果 = 执行函数(日志);
      return { ok: true, name: 名称, logs: 日志, result: 结果 || null };
    } catch (错误) {
      return { ok: false, name: 名称, logs: 日志, failedAt: String(错误?.message || 错误 || '未知失败') };
    }
  }

  async function 运行召唤聚合夹具(名称 = '') {
    const 夹具名 = 归一化召唤夹具名称(名称);
    if (夹具名 === 'UI预览') {
      const 临时 = await 挂载临时召唤夹具战斗UI();
      try {
        return 包装召唤夹具结果('召唤:UI预览', 日志 => {
          const 队列 = 临时.容器.querySelector('#ui-summon-queue');
          const 卡片 = 临时.容器.querySelector('.summon-card');
          const 按钮 = 临时.容器.querySelector('.summon-recall-btn');
          if (!队列 || 队列.hidden) throw new Error('UI队列未显示');
          if (!卡片) throw new Error('召唤卡片未渲染');
          if (!按钮) throw new Error('单体收回按钮缺失');
          按钮.click();
          const 动作 = window.BattleUI?.state?.selectedAction || {};
          if (动作.action_type !== '收回召唤' || !String(动作.target_name || '').trim()) throw new Error('收回动作未携带召唤键');
          日志.push('UI队列、卡片和单体收回动作已验证');
          return { summonQueue: true, recallTarget: 动作.target_name };
        });
      } finally {
        临时.清理();
      }
    }
    const 临时 = await 挂载临时召唤夹具战斗UI();
    try {
      if (typeof window.__LWCS_RUN_SUMMON_FIXTURE_BATCH__ !== 'function') {
        throw new Error('召唤夹具运行器未挂载');
      }
      const 运行结果 = window.__LWCS_RUN_SUMMON_FIXTURE_BATCH__(夹具名);
      return 包装召唤夹具结果(名称 || '召唤:批量', 日志 => {
        (运行结果?.results || []).forEach(item => 日志.push(`${item?.name || '召唤夹具'}:${item?.ok ? 'ok' : item?.failedAt || 'fail'}`));
        if (!运行结果 || 运行结果.ok !== true) throw new Error(`召唤夹具返回失败:${日志.join(';') || '无明细'}`);
        return 运行结果;
      });
    } finally {
      临时.清理();
    }
  }

  function 注册召唤夹具聚合入口() {
    if (window.__LWCS_SUMMON_FIXTURE_AGGREGATED__) return;
    const 原列表函数 = typeof window.__LWCS_LIST_SKILL_FIXTURES__ === 'function'
      ? window.__LWCS_LIST_SKILL_FIXTURES__.bind(window)
      : null;
    const 原运行函数 = typeof window.__LWCS_RUN_SKILL_FIXTURE_BATCH__ === 'function'
      ? window.__LWCS_RUN_SKILL_FIXTURE_BATCH__.bind(window)
      : null;
    window.__LWCS_LIST_SKILL_FIXTURES__ = () => {
      const 原列表 = 原列表函数 ? 原列表函数() : [];
      return Array.from(new Set([...(Array.isArray(原列表) ? 原列表 : []), ...召唤夹具名称列表]));
    };
    window.__LWCS_RUN_SKILL_FIXTURE_BATCH__ = async (名称 = '') => {
      const 文本 = String(名称 || '').trim();
      if (!文本) {
        const 结果列表 = [];
        if (原运行函数) 结果列表.push(await 原运行函数(''));
        for (const 召唤夹具名 of 召唤夹具名称列表) {
          结果列表.push(await 运行召唤聚合夹具(召唤夹具名));
        }
        return { ok: 结果列表.every(item => item?.ok !== false), results: 结果列表 };
      }
      if (/^召唤[:：]/.test(文本)) return 运行召唤聚合夹具(文本);
      return 原运行函数 ? 原运行函数(文本) : { ok: false, name: 文本, failedAt: '未找到夹具' };
    };
    window.__LWCS_SUMMON_FIXTURE_AGGREGATED__ = true;
  }

  注册召唤夹具聚合入口();


  function isCombatActiveForBattleInline(snapshot) {
    const combatData = deepGet(snapshot, 'rootData.world.战斗', {});
    return !!(
      combatData &&
      typeof combatData === 'object' &&
      combatData.进行中 &&
      isSnapshotPlayerControlled(snapshot)
    );
  }

  function 读取战斗复入快照(候选快照 = null) {
    const 快照列表 = [候选快照, liveSnapshot, lastRenderableSnapshot].filter(
      快照 => 快照 && typeof 快照 === 'object' && 快照.rootData,
    );
    const 有效快照 = 快照列表.find(快照 => isCombatActiveForBattleInline(快照));
    if (有效快照) return 有效快照;
    const 战斗数据 = window.BattleUI?.state?.combatData || window.BattleUIBridge?.getMVU?.('world.战斗') || null;
    if (!战斗数据 || typeof 战斗数据 !== 'object' || !战斗数据.进行中) return 快照列表[0] || null;
    const 根数据 = readLatestMvuDataByEditor() || {};
    if (!根数据.world || typeof 根数据.world !== 'object') 根数据.world = {};
    根数据.world.战斗 = 战斗数据;
    return buildSnapshot(根数据);
  }




  function removeBattleReturnEntries() {
    document.querySelectorAll('[data-mvu-battle-return="1"]').forEach(node => node.remove());
  }


  function syncBattleReturnEntries() {}

  function scheduleBattleReturnEntrySync(snapshot, isActive) {
    const token = ++battleReturnEntrySyncToken;
    const 初始快照 = snapshot && typeof snapshot === 'object' && snapshot.rootData ? snapshot : null;
    const run = () => {
      if (token !== battleReturnEntrySyncToken) return;
      const latestSnapshot = isActive
        ? 读取战斗复入快照(初始快照)
        : liveSnapshot || lastRenderableSnapshot || 初始快照;
      syncBattleReturnEntries(latestSnapshot, isActive && isCombatActiveForBattleInline(latestSnapshot));
    };
    if (typeof window.requestAnimationFrame === 'function') {
      window.requestAnimationFrame(run);
    }
    [80, 240, 520].forEach(delay => window.setTimeout(run, delay));
  }

  function 关闭座舱战斗屏() {
    if (window.COCKPIT?.battleShown?.()) window.COCKPIT.showBattle(false);
  }

  function openBattleInlineSurface() {
    // 战斗终端只挂在座舱战斗屏里（旧内嵌详情面已删除）
    const 座舱 = window.COCKPIT;
    if (!座舱?.mounted || typeof 座舱.battleHost !== 'function') return Promise.resolve(null);
    const 宿主 = 座舱.battleHost();
    if (宿主 && !getBattleInlineHost()) 宿主.innerHTML = buildBattleInlineHostMarkup();
    座舱.showBattle(true);
    return Promise.resolve(getBattleInlineHost());
  }


  const COMBAT_PARTICIPANT_STAT_KEYS = [
    '年龄',
    '等级',
    '天赋梯队',
    '邪魂师',
    'HP',
    'HP上限',
    '魂力',
    '魂力上限',
    '精神力',
    '精神力上限',
    '力量',
    '防御',
    '敏捷',
    '体力',
    '体力上限',
  ];

  function buildCombatParticipantFromSnapshotChar(snapshot, charKey, faction = '敌对') {
    const chars = deepGet(snapshot, 'rootData.char', {});
    const sourceChar = chars && typeof chars === 'object' ? chars[charKey] : null;
    if (!sourceChar || typeof sourceChar !== 'object') return null;
    const participant = cloneJsonValue(sourceChar, {});
    const rootData = snapshot && snapshot.rootData && typeof snapshot.rootData === 'object' ? snapshot.rootData : {};
    const hydrateEquipmentItem = (item = {}) => {
      if (!item || typeof item !== 'object' || Array.isArray(item)) return item;
      const itemName = toText(item.名称 || item.name || item.物品名, '').trim();
      if (!itemName || itemName === '无') return item;
      const hydrated = 合并物品定义与状态_桥接(rootData, itemName, item);
      return hydrated && typeof hydrated === 'object' && !Array.isArray(hydrated) ? hydrated : item;
    };
    if (participant.装备 && typeof participant.装备 === 'object' && !Array.isArray(participant.装备)) {
      ['武器', '防具', '机甲'].forEach(slot => {
        if (participant.装备[slot] && typeof participant.装备[slot] === 'object') participant.装备[slot] = hydrateEquipmentItem(participant.装备[slot]);
      });
      Object.entries(participant.装备.斗铠?.部件 || {}).forEach(([partSlot, part]) => {
        if (part && typeof part === 'object') participant.装备.斗铠.部件[partSlot] = hydrateEquipmentItem(part);
      });
      Object.entries(participant.装备.魂导器?.装配 || {}).forEach(([toolSlot, tool]) => {
        if (tool && typeof tool === 'object') participant.装备.魂导器.装配[toolSlot] = hydrateEquipmentItem(tool);
      });
    }
    if (participant.魂骨 && typeof participant.魂骨 === 'object' && !Array.isArray(participant.魂骨)) {
      Object.entries(participant.魂骨).forEach(([boneSlot, bone]) => {
        if (bone && typeof bone === 'object') participant.魂骨[boneSlot] = hydrateEquipmentItem(bone);
      });
    }
    if (participant.背包 && typeof participant.背包 === 'object' && !Array.isArray(participant.背包)) {
      Object.entries(participant.背包).forEach(([itemName, item]) => {
        if (!item || typeof item !== 'object' || Array.isArray(item)) return;
        const definition = 查找物品定义_桥接(rootData, itemName);
        if (!definition) return;
        participant.背包[itemName] = {
          ...cloneJsonValue(definition.定义, {}),
          ...item,
          ...(definition.定义.名称 ? { id: itemName } : {}),
          物品分类: definition.分类,
        };
      });
    }
    const stat = participant.属性 && typeof participant.属性 === 'object' ? participant.属性 : {};
    const status = participant.状态 && typeof participant.状态 === 'object' ? participant.状态 : {};
    participant.name = toText(participant.name || deepGet(participant, 'base.name', ''), charKey);
    participant.势力 = faction;
    participant.状态 = status;
    COMBAT_PARTICIPANT_STAT_KEYS.forEach(key => {
      if (stat[key] !== undefined) participant[key] = stat[key];
    });
    participant.等级 = toNumber(participant.等级, toNumber(stat.等级, 1));
    participant.系别 = toText(participant.系别, 取角色主武魂系别_桥接(participant, '未知系'));
    participant.HP上限 = Math.max(1, toNumber(participant.HP上限, toNumber(stat.HP上限, toNumber(stat.体力上限, 1))));
    participant.HP = Math.max(0, toNumber(participant.HP, toNumber(stat.HP, toNumber(stat.体力, participant.HP上限))));
    participant.体力上限 = Math.max(1, toNumber(participant.体力上限, toNumber(stat.体力上限, 1)));
    participant.体力 = Math.max(0, toNumber(participant.体力, toNumber(stat.体力, participant.体力上限)));
    participant.魂力上限 = Math.max(1, toNumber(participant.魂力上限, toNumber(stat.魂力上限, 1)));
    participant.魂力 = Math.max(0, toNumber(participant.魂力, toNumber(stat.魂力, participant.魂力上限)));
    participant.精神力上限 = Math.max(1, toNumber(participant.精神力上限, toNumber(stat.精神力上限, 1)));
    participant.精神力 = Math.max(0, toNumber(participant.精神力, toNumber(stat.精神力, participant.精神力上限)));
    participant.力量 = Math.max(0, toNumber(participant.力量, toNumber(stat.力量, 1)));
    participant.防御 = Math.max(0, toNumber(participant.防御, toNumber(stat.防御, 1)));
    participant.敏捷 = Math.max(0, toNumber(participant.敏捷, toNumber(stat.敏捷, 1)));
    participant.状态效果 = cloneJsonValue(participant.状态效果 || stat.状态效果 || {}, {});
    delete participant.持续效果;
    delete participant.蓄力技能;
    participant.存活 = status.存活 !== false;
    participant.状态.死亡tick = participant.存活 ? -1 : Math.max(-1, toNumber(status.死亡tick, -1));
    participant.状态.死亡类型 = participant.存活 ? '无' : toText(status.死亡类型, '意外');
    return participant;
  }

  function 读取角色间好感度(snapshot, leftKey = '', rightKey = '') {
    const chars = deepGet(snapshot, 'rootData.char', {});
    const left = chars && typeof chars === 'object' ? chars[leftKey] : null;
    const right = chars && typeof chars === 'object' ? chars[rightKey] : null;
    const rightNames = [rightKey, toText(right && right.name, ''), toText(deepGet(right, 'base.name', ''), '')].filter(
      Boolean,
    );
    const leftNames = [leftKey, toText(left && left.name, ''), toText(deepGet(left, 'base.name', ''), '')].filter(
      Boolean,
    );
    for (const name of rightNames) {
      const value = Number(deepGet(left, ['社交', '关系', name, '好感度'], NaN));
      if (Number.isFinite(value)) return value;
    }
    for (const name of leftNames) {
      const value = Number(deepGet(right, ['社交', '关系', name, '好感度'], NaN));
      if (Number.isFinite(value)) return value;
    }
    return 0;
  }

  function 允许已有参战者压制等级(snapshot, charKey = '') {
    const activeRaw =
      toText(snapshot && snapshot.activeName, '') || toText(deepGet(snapshot, 'rootData.sys.玩家名', ''), '');
    const activeKey = resolveSnapshotCharKey(snapshot, activeRaw);
    if (!activeKey || !charKey) return false;
    if (activeKey === charKey) return true;
    return 读取角色间好感度(snapshot, activeKey, charKey) >= 20;
  }

  function 应用已有参战者种子实力封顶(snapshot, charKey, 参战者, 种子 = {}) {
    if (!参战者 || typeof 参战者 !== 'object' || !种子 || typeof 种子 !== 'object') return 参战者;
    if (String(种子.单位性质 || '').trim() !== '人类') return 参战者;
    if (!允许已有参战者压制等级(snapshot, charKey)) return 参战者;
    const 限制等级 = Math.floor(Number(种子.等级));
    if (!Number.isFinite(限制等级) || 限制等级 <= 0) return 参战者;
    const 属性 = 参战者.属性 && typeof 参战者.属性 === 'object' ? 参战者.属性 : {};
    const 实际等级 = Math.floor(toNumber(参战者.等级, toNumber(属性.等级, 限制等级)));
    if (实际等级 <= 限制等级) return 参战者;
    const 限制基准 = getTemporaryBattleBaseStats(限制等级);
    参战者.实力压制 = {
      刻意压制等级: true,
      原始等级: 实际等级,
      压制等级: 限制等级,
      说明: `${toText(参战者.name || 参战者.名称, '参战者')}刻意将战斗实力压制到${限制等级}级`,
    };
    const 字段映射 = [
      ['HP上限', 'vit_max'],
      ['体力上限', 'vit_max'],
      ['魂力上限', 'sp_max'],
      ['精神力上限', 'men_max'],
      ['力量', 'str'],
      ['防御', 'def'],
      ['敏捷', 'agi'],
    ];
    参战者.等级 = 限制等级;
    属性.等级 = 限制等级;
    字段映射.forEach(([字段名, 基准名]) => {
      const 限制值 = Math.max(1, Math.floor(Number(限制基准[基准名] || 1)));
      const 当前值 = toNumber(参战者[字段名], toNumber(属性[字段名], 限制值));
      const 下限值 = Math.min(当前值, 限制值);
      参战者[字段名] = 下限值;
      属性[字段名] = 下限值;
    });
    [
      ['HP', 'HP上限'],
      ['体力', '体力上限'],
      ['魂力', '魂力上限'],
      ['精神力', '精神力上限'],
    ].forEach(([当前字段, 上限字段]) => {
      const 上限值 = Math.max(0, toNumber(参战者[上限字段], toNumber(属性[上限字段], 0)));
      const 当前值 = Math.max(0, toNumber(参战者[当前字段], toNumber(属性[当前字段], 上限值)));
      const 下限值 = Math.min(当前值, 上限值);
      参战者[当前字段] = 下限值;
      属性[当前字段] = 下限值;
    });
    参战者.属性 = 属性;
    return 参战者;
  }

  function normalizeBattleSeedParticipant(seed, fallbackName = '') {
    if (Array.isArray(seed)) {
      const firstValid = seed.find(item => item !== undefined && item !== null && item !== '');
      return firstValid === undefined ? null : normalizeBattleSeedParticipant(firstValid, fallbackName);
    }
    if (typeof seed === 'string' || typeof seed === 'number') {
      const normalizedName = toText(seed, fallbackName);
      return normalizedName ? { name: normalizedName } : null;
    }
    if (!seed || typeof seed !== 'object' || Array.isArray(seed)) return null;
    const normalized = cloneJsonValue(seed, {});
    const normalizedName = toText(normalized.name, fallbackName);
    if (!normalizedName) return null;
    normalized.name = normalizedName;
    return normalized;
  }

  const BATTLE_SOUL_BEAST_STANDARD_SPECIES = Object.freeze([
    '龙类',
    '蛛类',
    '熊类',
    '植物系',
    '海魂兽',
    '鸟类',
    '猫科',
    '蛇类',
  ]);

  const BATTLE_SOUL_BEAST_QUALITY_TIER_MULTIPLIERS = Object.freeze({
    弱小: 0.8,
    普通: 1.0,
    强力: 1.2,
    顶级: 1.45,
    霸主: 1.6,
  });


  const BATTLE_ABYSS_STANDARD_RACES = Object.freeze([
    '四爪蝙蝠',
    '六爪蝙蝠',
    '深渊炸弹蜂',
    '噬蜥',
    '六爪魔',
    '巴安',
    '守护天牛',
    '深渊猛犸',
    '深渊魔傀',
    '黑皇族',
    '魔魅族',
    '深渊恶镰',
    '附体魔',
  ]);

  function getSoulBeastAgeBandName(age = 1) {
    const value = Math.max(1, Math.floor(Number(age || 1)));
    if (value >= 100000) return '十万年';
    if (value >= 10000) return '万年';
    if (value >= 1000) return '千年';
    if (value >= 100) return '百年';
    return '十年';
  }

  function buildSoulBeastBestiaryKey(age = 1, specificSpecies = '') {
    const species = String(specificSpecies || '').trim();
    return species ? `${getSoulBeastAgeBandName(age)}${species}` : '';
  }

  function normalizeSoulBeastQualityTier(value = '') {
    const text = String(value || '').trim();
    if (Object.prototype.hasOwnProperty.call(BATTLE_SOUL_BEAST_QUALITY_TIER_MULTIPLIERS, text)) return text;
    return '普通';
  }

  function getSoulBeastQualityTierMultiplier(value = '') {
    return Number(BATTLE_SOUL_BEAST_QUALITY_TIER_MULTIPLIERS[normalizeSoulBeastQualityTier(value)] || 1);
  }

  const BATTLE_TEMPORARY_TYPE_MULTIPLIERS = Object.freeze({
    强攻系: { sp_max: 1.0, men_max: 1.0, str: 1.0, def: 1.0, agi: 1.0, vit_max: 1.0 },
    防御系: { sp_max: 1.0, men_max: 1.0, str: 0.9, def: 1.5, agi: 0.7, vit_max: 1.0 },
    敏攻系: { sp_max: 1.0, men_max: 1.0, str: 0.8, def: 0.7, agi: 1.6, vit_max: 0.8 },
    控制系: { sp_max: 1.0, men_max: 1.2, str: 0.9, def: 0.8, agi: 1.1, vit_max: 0.9 },
    辅助系: { sp_max: 1.2, men_max: 1.2, str: 0.7, def: 0.6, agi: 0.8, vit_max: 0.7 },
    食物系: { sp_max: 1.2, men_max: 1.2, str: 0.7, def: 0.6, agi: 0.8, vit_max: 0.7 },
    治疗系: { sp_max: 1.2, men_max: 1.2, str: 0.7, def: 0.6, agi: 0.8, vit_max: 0.7 },
  });

  function getTemporaryBattleBaseStats(level = 1) {
    const 基础属性函数 = 读取窗口函数('__LWCS_GET_BASE_STATS__');
    if (typeof 基础属性函数 !== 'function') {
      throw new Error('MVU基础属性函数未加载');
    }
    const 基础 = 基础属性函数(level);
    return {
      sp_max: Math.floor(Number(基础.sp_max || 0)),
      men_max: Math.floor(Number(基础.men_max || 0)),
      str: Math.floor(Number(基础.str || 0)),
      def: Math.floor(Number(基础.def || 0)),
      agi: Math.floor(Number(基础.agi || 0)),
      vit_max: Math.floor(Number(基础.vit_max || 0)),
    };
  }

  function buildSkillDesignConfirmState(snapshot) {
    const state = 待处理技能设计确认 && typeof 待处理技能设计确认 === 'object' ? 待处理技能设计确认 : null;
    if (!state) return null;
    if (state.growthRecord && typeof state.growthRecord === 'object') {
      return {
        ...state,
        charName: toText(state.charName || state.growthRecord.角色名, ''),
        sourceLabel: toText(state.sourceLabel, '成长技能模板'),
        skillName: normalizeSkillUiText(state.growthRecord.魂技名 || state.growthRecord.技能名称, '成长技能'),
        signature: toText(state.signature, ''),
      };
    }
    const previewKey = toText(state.previewKey, '').trim();
    const previewMeta = parseSkillDesignerPreviewKey(previewKey);
    if (!previewKey || !previewMeta || !Array.isArray(previewMeta.path) || !previewMeta.path.length) return null;
    const safeSnapshot = snapshot && typeof snapshot === 'object' ? snapshot : liveSnapshot || lastRenderableSnapshot;
    const skillSource =
      safeSnapshot && safeSnapshot.rootData ? deepGet(safeSnapshot.rootData, previewMeta.path, null) : null;
    if (!skillSource || typeof skillSource !== 'object') return null;
    return {
      ...state,
      previewKey,
      previewMeta,
      charName: toText(state.charName, safeSnapshot ? toText(safeSnapshot.activeName, '') : ''),
      sourceLabel: toText(state.sourceLabel, previewMeta.category || '技能'),
      skillName: normalizeSkillUiText(skillSource['魂技名'] || skillSource.name, previewMeta.label || '新技能'),
      signature: toText(state.signature, previewKey),
    };
  }

  function 打开技能设计确认(确认数据 = {}) {
    const previewKey = toText(确认数据.previewKey, '').trim();
    if (!previewKey || !isSkillDesignerPreviewKey(previewKey)) return false;
    const signature = toText(确认数据.signature || previewKey, previewKey);
    const currentState = buildSkillDesignConfirmState(liveSnapshot || lastRenderableSnapshot);
    if (currentState && (currentState.previewKey === previewKey || currentState.signature === signature)) {
      openDetailPreview(PENDING_SKILL_DESIGN_PREVIEW_KEY, {
        preserveMapDispatchContext: true,
        replace: true,
      });
      return true;
    }
    待处理技能设计确认 = {
      previewKey,
      charName: toText(确认数据.charName, ''),
      sourceLabel: toText(确认数据.sourceLabel, '技能'),
      returnPreviewKey: toText(确认数据.returnPreviewKey, ''),
      submitAfterSave: 确认数据.submitAfterSave !== false,
      signature,
    };
    if (!buildSkillDesignConfirmState(liveSnapshot || lastRenderableSnapshot)) {
      待处理技能设计确认 = null;
      return false;
    }
    openDetailPreview(PENDING_SKILL_DESIGN_PREVIEW_KEY, {
      preserveMapDispatchContext: true,
      replace: true,
    });
    return true;
  }

  function 继续现有技能获得流程() {
    const state = buildSkillDesignConfirmState(liveSnapshot || lastRenderableSnapshot);
    if (state?.growthRecord && state.signature) 已跳过成长技能确认签名.add(state.signature);
    const skillName = normalizeSkillUiText(state?.skillName, '当前技能');
    const returnPreviewKey = toText(state?.returnPreviewKey, '').trim();
    待处理技能设计确认 = null;
    if (returnPreviewKey) {
      openDetailPreview(returnPreviewKey, { preserveMapDispatchContext: true, replace: true });
    } else {
      closeDetailSurface({
        surface: currentUnifiedPreviewKey === PENDING_SKILL_DESIGN_PREVIEW_KEY ? 'unified' : 'modal',
      });
    }
    showUiToast(`已保留【${skillName}】。`, 'success', 2200);
  }

  function 构建成长技能模板预览键(记录 = {}) {
    const 角色名 = toText(记录 && 记录.角色名, '').trim();
    const 写入路径 = toText(记录 && 记录.写入路径, '').trim();
    const 写入类型 = toText(记录 && 记录.写入类型, '').trim();
    if (!角色名 || !写入路径) return '';
    const path = ['char', 角色名, ...写入路径.split('.').map(片段 => toText(片段, '').trim()).filter(Boolean)];
    if (写入类型 === '武魂融合技' && path[path.length - 1] !== '技能数据') path.push('技能数据');
    return buildSkillDesignerPreviewKey({
      path,
      label: toText(记录.魂技名 || 记录.技能名称, path[path.length - 1] || '成长技能'),
      category: 写入类型 || '成长技能',
      scope: 写入类型 === '自创魂技' ? '自创魂技' : 写入类型 === '武魂融合技' ? '武魂融合技' : '魂技',
    });
  }

  async function 应用成长技能模板并打开设计台(记录 = {}) {
    const runtime = 读取MVUSchema运行时接口_桥接();
    if (!runtime || typeof runtime.应用内置角色成长技能模板记录 !== 'function') {
      showUiToast('成长技能模板接口不可用。', 'error', 4200);
      return false;
    }
    let previewKey = 构建成长技能模板预览键(记录);
    let result = null;
    try {
      await mutateStatDataByEditor(
        statData => {
          result = runtime.应用内置角色成长技能模板记录(statData, 记录);
          if (!result || result.changed !== true) throw new Error(result?.reason || 'growth_skill_not_written');
        },
        { force: true },
      );
      await refreshLiveSnapshot({ force: true });
    } catch (error) {
      showUiToast(error && error.message ? error.message : '成长技能写入失败。', 'error', 4200);
      return false;
    }
    待处理技能设计确认 = null;
    if (previewKey && isSkillDesignerPreviewKey(previewKey)) {
      openDetailPreview(previewKey, { preserveMapDispatchContext: true, replace: true });
    } else {
      closeModal();
      showUiToast('成长技能已采用。', 'info', 2200);
    }
    return true;
  }

  function 打开待处理技能设计台(snapshot) {
    const state = buildSkillDesignConfirmState(snapshot);
    if (!state) throw new Error('当前没有可设计的技能。');
    if (state.growthRecord) {
      void 应用成长技能模板并打开设计台(state.growthRecord);
      return;
    }
    openDetailPreview(state.previewKey, { preserveMapDispatchContext: true, replace: true });
  }

  async function 准备剧情技能自行设计(选项 = {}) {
    const snapshot = liveSnapshot || lastRenderableSnapshot || (await getLiveSnapshot());
    const activeName = toText(snapshot && snapshot.activeName, '');
    const 输入角色名 = toText(选项.角色 || 选项.charName || 选项.character || activeName, activeName);
    const charKey = resolveSnapshotCharKey(snapshot, 输入角色名) || resolveSnapshotCharKey(snapshot, activeName) || activeName;
    if (!charKey) throw new Error('未找到当前角色，无法新建技能设计。');
    const skillType = /武魂融合技/.test(toText(选项.技能类型 || 选项.type || '', '')) ? '武魂融合技' : '自创魂技';
    const skillKey = `剧情技能_${Date.now().toString(36)}_${Math.random().toString(36).slice(2, 6)}`;
    const skillLabel = toText(选项.label || 选项.技能名称 || 选项.name, '剧情新技能');
    const path = skillType === '武魂融合技'
      ? ['char', charKey, '武魂融合技', skillLabel, '技能数据']
      : ['char', charKey, '自创魂技', skillKey];
    const previewKey = buildSkillDesignerPreviewKey({
      path,
      label: skillLabel,
      category: skillType,
      scope: skillType,
    });
    await mutateStatDataByEditor(
      statData => {
        const charData = deepGet(statData, ['char', charKey], null);
        if (!charData || typeof charData !== 'object') throw new Error('未找到当前角色。');
        if (skillType === '武魂融合技') {
          if (!charData.武魂融合技 || typeof charData.武魂融合技 !== 'object' || Array.isArray(charData.武魂融合技)) charData.武魂融合技 = {};
          if (!charData.武魂融合技[skillLabel] || typeof charData.武魂融合技[skillLabel] !== 'object' || Array.isArray(charData.武魂融合技[skillLabel])) charData.武魂融合技[skillLabel] = {};
          if (!charData.武魂融合技[skillLabel].技能数据) {
            charData.武魂融合技[skillLabel].技能数据 = {
              魂技名: skillLabel,
              画面描述: '未知',
              效果描述: '未知',
              _效果数组: [],
            };
          }
          return;
        }
        if (!charData.自创魂技 || typeof charData.自创魂技 !== 'object' || Array.isArray(charData.自创魂技)) charData.自创魂技 = {};
        if (!charData.自创魂技[skillKey]) {
          charData.自创魂技[skillKey] = {
            魂技名: skillLabel,
            画面描述: '未知',
            效果描述: '未知',
            _效果数组: [],
          };
        }
      },
      { force: true },
    );
    await refreshLiveSnapshot({ force: true });
    const opened = 打开技能设计确认({
      previewKey,
      charName: 输入角色名 || activeName || charKey,
      sourceLabel: toText(选项.sourceLabel, '剧情获得技能'),
      submitAfterSave: true,
      signature: `story_skill::${charKey}::${skillType}::${skillLabel}`,
    });
    if (!opened) throw new Error('技能记录创建后无法打开确认页。');
    return { ok: true, previewKey, skillKey };
  }

  function 规范化传授内容类型(内容类型 = '') {
    const 文本 = toText(内容类型, '').trim();
    if (/情报|信息|秘密|机密/.test(文本)) return '情报';
    if (/功法|心法|绝学/.test(文本)) return '功法';
    if (/秘技|战斗技巧|技巧|技艺/.test(文本)) return '战斗技巧';
    if (/自创魂技|魂技|技能/.test(文本)) return '自创魂技';
    return 文本 || '情报';
  }

  function 构建功法学习记录_桥接(功法名 = '', 描述 = '未知', 根数据 = {}) {
    const 名称 = toText(功法名, '').trim();
    const 功法描述 = normalizeSkillUiText(描述, '未知');
    if (名称 !== '紫极魔瞳') return { 描述: 功法描述 };
    const 当前tick = Math.max(0, Math.floor(toNumber(deepGet(根数据, ['world', '时间', 'tick'], 0), 0)));
    return { 境界: '纵观', lv: 1, 获得tick: 当前tick, 描述: 功法描述 };
  }

  function 解析传授模块意图请求(snapshot, payload = {}) {
    const 学生名 = toText(payload.学生 || payload.student || payload.角色 || payload.char || snapshot?.activeName, '').trim();
    const 老师名 = toText(payload.老师 || payload.teacher || payload.对象 || payload.npc || payload.target, '').trim();
    const 内容名称 = toText(payload.内容名称 || payload.名称 || payload.name || payload.内容 || payload.targetName, '').trim();
    const 内容类型 = 规范化传授内容类型(payload.内容类型 || payload.type || payload.category || payload.类型);
    const 结果 = toText(payload.结果 || payload.result || '成立', '成立').trim();
    const 理由 = toText(payload.理由 || payload.reason, '').trim();
    const 效果数组 = Array.isArray(payload._效果数组) ? payload._效果数组 : [];
    const 已定义 = payload.已定义 === true || (payload.已定义 !== false && 效果数组.length > 0);
    const 学生 = resolveSnapshotCharacter(snapshot, 学生名 || snapshot?.activeName);
    const 老师 = 老师名 ? resolveSnapshotCharacter(snapshot, 老师名) : { key: '', displayName: '', char: null };
    if (!学生.key || !学生.char) return { invalid: true, reason: 'teaching_student_unresolved', 学生: 学生名, 老师: 老师名, 内容类型, 内容名称, 结果, 理由 };
    if (!内容名称) return { invalid: true, reason: 'teaching_content_missing', 学生: 学生.displayName || 学生.key, 老师: 老师.displayName || 老师名, 内容类型, 内容名称, 结果, 理由 };
    return {
      动作: toText(payload.动作 || payload.action, '请教'),
      老师: 老师.displayName || 老师名,
      teacherKey: 老师.key || '',
      学生: 学生.displayName || 学生.key,
      studentKey: 学生.key,
      内容类型,
      内容名称,
      结果,
      理由,
      _效果数组: 效果数组,
      已定义,
      画面描述: toText(payload.画面描述, '').trim(),
      效果描述: toText(payload.效果描述, '').trim(),
      承载方式: toText(payload.承载方式, '').trim(),
      消耗: payload.消耗,
      前摇: payload.前摇,
    };
  }

  async function 打开传授技能设计台(request = {}) {
    const studentKey = toText(request.studentKey, '').trim();
    const skillLabel = toText(request.内容名称, '').trim();
    const 内容类型 = 规范化传授内容类型(request.内容类型);
    if (!studentKey || !skillLabel) throw new Error('传授内容缺少学生或名称。');
    const scope = 内容类型 === '功法' ? 'art' : '自创魂技';
    const category = 内容类型 === '功法' ? '功法' : '自创魂技';
    const parentKey = 内容类型 === '功法' ? '功法' : '自创魂技';
    const recordKey = skillLabel;
    const 已定义 = 内容类型 !== '功法' && request.已定义 === true && Array.isArray(request._效果数组) && request._效果数组.length > 0;
    const previewKey = buildSkillDesignerPreviewKey({
      path: ['char', studentKey, parentKey, recordKey],
      label: skillLabel,
      category,
      scope,
    });
    await mutateStatDataByEditor(
      statData => {
        const charData = deepGet(statData, ['char', studentKey], null);
        if (!charData || typeof charData !== 'object') throw new Error('未找到学生角色。');
        if (!charData[parentKey] || typeof charData[parentKey] !== 'object' || Array.isArray(charData[parentKey]))
          charData[parentKey] = {};
        if (已定义) {
          charData[parentKey][recordKey] = {
            魂技名: skillLabel,
            画面描述: normalizeSkillUiText(request.画面描述, '未知'),
            效果描述: normalizeSkillUiText(request.效果描述, '未知'),
            承载方式: toText(request.承载方式, '直接生效') || '直接生效',
            消耗: request.消耗 ?? '无',
            前摇: toNumber(request.前摇, 0),
            _效果数组: cloneJsonValue(request._效果数组, []),
          };
          return;
        }
        if (!charData[parentKey][recordKey]) {
          charData[parentKey][recordKey] = 内容类型 === '功法'
            ? 构建功法学习记录_桥接(skillLabel, '未知', statData)
            : { 魂技名: skillLabel, 画面描述: '未知', 效果描述: '未知', _效果数组: [] };
        }
      },
      { force: true },
    );
    await refreshLiveSnapshot({ force: true });
    if (已定义) return { ok: true, recordKey, 内容类型, 已定义: true, skipDesigner: true };
    打开技能设计确认({
      previewKey,
      charName: toText(request.学生, studentKey),
      sourceLabel: `${toText(request.老师, '他人')}传授${内容类型}`,
      submitAfterSave: true,
    });
    return { ok: true, previewKey, recordKey, 内容类型 };
  }

  async function 执行传授模块意图路由(snapshot, request = {}) {
    if (request.invalid) return 构建模块路由失败结果('teaching', request, request.reason || 'teaching_request_invalid');
    if (toText(request.结果, '成立') !== '成立') {
      return 构建模块路由成功结果('teaching', request, {
        dispatchMode: 'patch',
        skipped: true,
        reason: 'teaching_not_established',
      });
    }
    const 内容类型 = 规范化传授内容类型(request.内容类型);
    if (内容类型 === '情报') {
      await mutateStatDataByEditor(
        statData => {
          const intelPath = ['char', request.studentKey, '已掌握情报'];
          let knowledges = deepGet(statData, intelPath, null);
          if (!Array.isArray(knowledges)) {
            deepSetMutable(statData, intelPath, []);
            knowledges = deepGet(statData, intelPath, null);
          }
          if (!knowledges.some(item => toText(item, '').trim() === request.内容名称)) knowledges.push(request.内容名称);
        },
        { force: true },
      );
      await refreshLiveSnapshot({ force: true });
      return 构建模块路由成功结果('teaching', request, { dispatchMode: 'patch', 内容类型 });
    }
    const result = await 打开传授技能设计台({ ...request, 内容类型 });
    return 构建模块路由成功结果('teaching', request, {
      dispatchMode: 'settled_summary',
      result,
    });
  }

  async function 执行新技能获得模块意图路由(snapshot, request = {}) {
    if (request.invalid) return 构建模块路由失败结果('skill_gain', request, request.reason || 'skill_gain_request_invalid');
    const result = await 准备剧情技能自行设计({
      角色: request.charKey || request.角色,
      技能名称: request.技能名称,
      技能类型: request.技能类型,
      sourceLabel: request.来源 ? `剧情新技能：${request.来源}` : '剧情新技能',
    });
    return 构建模块路由成功结果('skill_gain', request, {
      dispatchMode: 'pending_confirmation',
      result,
    });
  }

  window.__LWCS_PROMPT_SKILL_DESIGN__ = async (选项 = {}) => {
    try {
      return await 准备剧情技能自行设计(选项);
    } catch (error) {
      showUiToast(error && error.message ? error.message : '技能设计入口打开失败。', 'error', 4200);
      return { ok: false, reason: error && error.message ? error.message : 'failed' };
    }
  };

  function hashTemporaryBattleSeed(seedText = '') {
    const text = String(seedText || '');
    let hash = 2166136261;
    for (let index = 0; index < text.length; index += 1) {
      hash ^= text.charCodeAt(index);
      hash = Math.imul(hash, 16777619);
    }
    return hash >>> 0;
  }

  function createTemporaryBattleRng(seedText = '') {
    let state = hashTemporaryBattleSeed(seedText) || 1;
    return () => {
      state = (Math.imul(state, 1664525) + 1013904223) >>> 0;
      return state / 4294967296;
    };
  }

  function withTemporaryBattleRandom(seedText, runner) {
    const rng = createTemporaryBattleRng(seedText);
    return runner(rng);
  }

  function pickTemporaryBattleItem(items = [], rng = Math.random) {
    if (!Array.isArray(items) || !items.length) return '';
    return items[Math.max(0, Math.min(items.length - 1, Math.floor(rng() * items.length)))] || items[0];
  }

  function pickTemporaryBattleInt(min = 0, max = min, rng = Math.random) {
    const low = Math.floor(Math.min(min, max));
    const high = Math.floor(Math.max(min, max));
    if (high <= low) return low;
    return low + Math.floor(rng() * (high - low + 1));
  }

  function createTemporaryBattleSkillShell(skillName = '战技') {
    return {
      魂技名: skillName,
      画面描述: '未知',
      效果描述: '未知',
      _效果数组: [],
    };
  }

  function buildTemporaryBattleSkillMap(skillCount = 0, skillNames = []) {
    const total = Math.max(0, Math.min(4, Math.floor(Number(skillCount || 0))));
    const skillMap = {};
    for (let index = 1; index <= total; index += 1) {
      const skillName = String(skillNames[index - 1] || `战技${index}`).trim() || `战技${index}`;
      skillMap[skillName] = createTemporaryBattleSkillShell(skillName);
    }
    return skillMap;
  }

  function buildTemporarySoulBeastSkillNames(species = '', specificSpecies = '', skillCount = 0) {
    const baseNames = {
      龙类: ['龙息冲击', '龙鳞护体', '龙爪裂空', '龙威震慑'],
      蛛类: ['毒丝缠束', '蛛矛突刺', '蛛网封锁', '剧毒侵蚀'],
      熊类: ['厚甲冲撞', '撕裂爪击', '震地重压', '狂暴扑杀'],
      植物系: ['藤蔓缠束', '花粉迷障', '根须穿刺', '生命汲取'],
      海魂兽: ['水刃切割', '潮汐冲撞', '水幕护体', '深海压迫'],
      鸟类: ['疾羽切割', '俯冲突袭', '风翼闪避', '锐鸣震慑'],
      猫科: ['迅影扑杀', '裂爪连击', '潜伏突袭', '野性爆发'],
      蛇类: ['毒牙突袭', '蛇影缠杀', '鳞甲偏转', '麻痹毒雾'],
    }[species] || ['撕裂爪击', '厚甲冲撞', '毒牙突袭', '藤蔓缠束'];
    return baseNames.slice(0, Math.max(0, Math.floor(Number(skillCount || 0))));
  }

  function buildTemporaryAbyssSkillNames(race = '', skillCount = 0) {
    const text = String(race || '').trim();
    let baseNames = ['深渊撕裂', '深渊冲撞', '浊能护体', '裂隙压迫'];
    if (/蝙蝠/.test(text)) baseNames = ['翼刃切割', '音波扰乱', '俯冲撕咬', '群翼遮蔽'];
    else if (/蜂/.test(text)) baseNames = ['爆裂蜂刺', '自爆冲击', '毒雾扩散', '蜂群围杀'];
    else if (/魔|巴安|天牛|猛犸|魔傀/.test(text)) baseNames = ['深渊重击', '浊甲护体', '蛮力践踏', '深渊震荡'];
    else if (/黑皇|魔魅|恶镰|附体/.test(text)) baseNames = ['浊能侵袭', '精神扰乱', '影刃切割', '附体压制'];
    return baseNames.slice(0, Math.max(0, Math.floor(Number(skillCount || 0))));
  }

  function buildTemporaryHumanSkillNames(combatType = '', skillCount = 0) {
    const baseNames = {
      强攻系: ['正面强击', '魂力爆发', '破阵重击', '战意压迫'],
      防御系: ['护体免伤', '坚壁反震', '重盾压制', '阵地固守'],
      敏攻系: ['迅步突刺', '连环切击', '闪身追击', '残影扰乱'],
      控制系: ['魂力束缚', '节奏干扰', '领域压迫', '封锁牵引'],
      辅助系: ['魂力增幅', '节奏支援', '状态稳定', '协同强化'],
      食物系: ['补给凝成', '体力补充', '魂力滋养', '状态调和'],
      治疗系: ['伤势修复', '气息稳定', '持续治疗', '生命回流'],
      召唤系: ['召唤牵引', '协同攻势', '召唤护卫', '群体压制'],
    }[combatType] || ['正面强击', '魂力爆发', '迅步突刺', '护体免伤'];
    return baseNames.slice(0, Math.max(0, Math.floor(Number(skillCount || 0))));
  }

  function estimateTemporaryHumanSkillCount(level = 1) {
    const safeLevel = Math.max(1, Math.floor(Number(level || 1)));
    if (safeLevel >= 80) return 4;
    if (safeLevel >= 50) return 3;
    if (safeLevel >= 30) return 2;
    return 1;
  }

  function estimateTemporaryMonsterSkillCount(unitNature = '魂兽', seed = {}) {
    if (unitNature === '魂兽') {
      const age = Math.max(0, Math.floor(Number(seed?.年限 || 0)));
      if (age >= 100000) return 4;
      if (age >= 10000) return 3;
      if (age >= 1000) return 2;
      return 1;
    }
    const tier = String(seed?.级别 || '').trim();
    if (tier === '深渊帝君' || tier === '深渊王者') return 4;
    if (tier === '高阶生物') return 3;
    if (tier === '中阶生物') return 2;
    return 1;
  }

