  async function handleMapAiRequest(event) {
    const detail = event && event.detail && typeof event.detail === 'object' ? event.detail : {};
    const playerInput = toText(detail.playerInput || detail.input || '', '').trim();
    const systemPrompt = toText(detail.systemPrompt || detail.prompt || '', '').trim();
    const meta = detail.meta && typeof detail.meta === 'object' ? detail.meta : {};
    if (!playerInput) return;
    detail.handled = true;
    if (toText(meta.requestKind, '') === 'map_travel_settled') await refreshLiveSnapshot({ force: true });
    const requestKind = toText(meta.requestKind, 'map_ai_request');
    if (requestKind === 'map_travel_settled') {
      登记本轮模块结算路径([['world', '动态地点']], { 记录本轮模块结算路径: true });
    }
    const 提交参数 = {
      requestKind,
      patchOps: Array.isArray(meta.patchOps) ? meta.patchOps : [],
    };
    if (meta.skipActionLock === true) 提交参数.skipActionLock = true;
    if (meta.noActionLock === true) 提交参数.noActionLock = true;
    detail.result = await dispatchUiAiRequest(playerInput, systemPrompt, 提交参数);
  }

  window.addEventListener('map-ai-request', handleMapAiRequest);

  async function handleMapMaintenanceRequest(event) {
    const detail = event && event.detail && typeof event.detail === 'object' ? event.detail : {};
    const patchOps = Array.isArray(detail.patchOps) ? detail.patchOps : [];
    if (!patchOps.length) return;
    try {
      await applyJsonPatchOpsByEditor(patchOps, { force: true });
      detail.delivery = { ok: true, channel: 'mvu_editor_patch', patchCount: patchOps.length };
      await refreshLiveSnapshot({ force: true });
      showUiToast(toText(detail.message, '地图维护已写入。'), 'info', 2400);
    } catch (error) {
      detail.delivery = { ok: false, channel: 'mvu_editor_patch', error: String((error && error.message) || error) };
      showUiToast(error && error.message ? error.message : '地图维护写入失败。', 'error', 4200);
      console.warn('[DragonUI] 地图维护写入失败', error);
    }
  }

  window.addEventListener('map-maintenance-request', handleMapMaintenanceRequest);

  async function handleMapTravelSettleRequest(event) {
    const detail = event && event.detail && typeof event.detail === 'object' ? event.detail : {};
    detail.handled = true;
    try {
      detail.result = await 结算地图移动请求(detail);
      if (!detail.result || detail.result.ok === false) {
        showUiToast(toText(detail.result && detail.result.reason, '地图移动结算失败。'), 'error', 4200);
      } else if (detail.result.alreadyThere) {
        showUiToast('已位于目标地点。', 'info', 1800);
      } else {
        showUiToast('移动已结算。', 'info', 1800);
      }
    } catch (error) {
      detail.result = { ok: false, reason: error && error.message ? error.message : 'map_travel_settle_failed' };
      showUiToast(detail.result.reason, 'error', 4200);
      console.warn('[DragonUI] 地图移动结算失败', error);
    }
  }

  window.addEventListener('map-travel-settle-request', handleMapTravelSettleRequest);
  window.__LWCS_SETTLE_MAP_TRAVEL__ = detail => 结算地图移动请求(detail);

  async function handleBattleMvuUpdateRequest(event) {
    const detail = event && event.detail && typeof event.detail === 'object' ? event.detail : {};
    const patchOps = Array.isArray(detail.patchOps) ? detail.patchOps : [];
    if (!patchOps.length) return;
    if (自动战斗延后写回次数 > 0) {
      自动战斗延后写回次数 -= 1;
      detail.delivery = { ok: true, channel: 'auto_battle_deferred_patch', patchCount: patchOps.length };
      return;
    }
    try {
      await applyBattlePatchOpsByEditor(patchOps);
      detail.delivery = { ok: true, channel: 'mvu_editor_patch', patchCount: patchOps.length };
      if (detail.combatData && detail.combatData.进行中 === false) {
        const 裁断文本 = toText(detail.combatData.裁断结果, '').trim();
        const 参战者名称 = collectBattleParticipantNames(detail.combatData);
        const 胜方 = 参战者名称.find(名称 => {
          const 位置 = 裁断文本.indexOf(名称);
          return 位置 >= 0 && /战胜|获胜|胜出/.test(裁断文本.slice(位置, 位置 + 名称.length + 8));
        });
        if (/平局|未分胜负/.test(裁断文本)) await 结算赛事战斗_桥接({ 平局: true });
        else if (胜方) await 结算赛事战斗_桥接({ 胜方 });
        else await 结算赛事战斗_桥接({ 技术失败: true });
      }
      await refreshLiveSnapshot({ force: true });
    } catch (error) {
      detail.delivery = { ok: false, channel: 'mvu_editor_patch', error: String((error && error.message) || error) };
      console.warn('[DragonUI] 战斗模块变量写入失败', error);
    }
  }

  function handleBattleUiCloseRequest(event) {
    const detail = event && event.detail && typeof event.detail === 'object' ? event.detail : {};
    detail.handled = true;
    const battleSnapshot = 读取战斗复入快照();
    if (isCombatActiveForBattleInline(battleSnapshot)) {
      battleInlineDismissed = true;
      scheduleBattleReturnEntrySync(battleSnapshot, true);
    }
    if (activeBattleUI && typeof activeBattleUI.destroy === 'function') activeBattleUI.destroy();
    activeBattleUI = null;
    battleInlineMountToken++;
    pendingBattleInlineMount = null;
    关闭座舱战斗屏();
    if (currentUnifiedPreviewKey === BATTLE_INLINE_PREVIEW_KEY && typeof window.__MVU_CLOSE_UNIFIED_PREVIEW__ === 'function') {
      window.__MVU_CLOSE_UNIFIED_PREVIEW__({ force: true });
    }
  }

  window.addEventListener('battle-ui-mvu-update-request', handleBattleMvuUpdateRequest);
  window.addEventListener('battle-ui-close-request', handleBattleUiCloseRequest);







